(window.WCD=window.WCD||[]).push(["politique",[["Q91",1,"politicien","Abraham Lincoln","L","Abraham Lincoln, né le 12 février 1809 à Hodgenville et mort assassiné le 15 avril 1865 à Washington, D.C., est un homme d'État américain. Il est le 16e président des États-Unis, en fonction du 4 mars 1861 jusqu'à sa mort, et le premier issu du Parti républicain.",114,"fr:Abraham_Lincoln","c:a/ab/Abraham_Lincoln_O-77_matte_collodion_print.jpg",{"cats":["politique","usa"]}],["Q352",2,"politicien","Adolf Hitler","L","Adolf Hitler, né le 20 avril 1889 à Braunau am Inn et mort suicidé le 30 avril 1945 à Berlin, est un idéologue d'extrême droite et un homme d'État allemand d'origine autrichienne. Fondateur et figure centrale du nazisme, il arrive au pouvoir en Allemagne en 1933 et instaure rapidement une dictature totalitaire au programme impérialiste, antisémite, raciste, homophobe, xénophobe, eugéniste et génocidaire, désignée sous le nom de Troisième Reich.",110,"fr:Adolf_Hitler","c:a/ab/Bundesarchiv_Bild_183-H1216-0500-002%2C_Adolf_Hitler.jpg"],["Q19673",3,"politicien","Al Gore","PC","Albert Arnold Gore, Jr. dit Al Gore, né le 31 mars 1948 à Washington, D.C., est un homme d'affaires et homme d'État américain, vice-président des États-Unis de 1993 à 2001.","Albert Arnold Gore, Jr.","fr:Al_Gore","c:c/c5/Al_Gore%2C_Vice_President_of_the_United_States%2C_official_portrait_1994.jpg"],["Q8409",5,"politicien","Alexandre le Grand","E","Alexandre le Grand ou Alexandre III, né le 21 juillet 356 av. J.-C. à Pella et mort le 11 juin 323 av. J.-C. à Babylone, est un roi de Macédoine et l'un des personnages les plus célèbres de l'Antiquité. Fils de Philippe II, élève d'Aristote et roi de Macédoine à partir de 336, il devient l'un des plus grands conquérants de l'histoire en prenant possession de l'immense Empire perse et en s'avançant jusqu'aux rives de l'Indus.","Alexandre le Grand ou Alexandre III, né le 21 juillet 356 av.","fr:Alexandre_le_Grand","c:5/56/Alexander_the_Great%2C_from_Alexandria%2C_Egypt%2C_3rd_cent._BCE%2C_Ny_Carlsberg_Glyptotek%2C_Copenhagen_%285%29_%2836375553176%29.jpg"],["Q2866",6,"politicien","Alexandre Loukachenko","PC","Alexandre Grigorievitch Loukachenko (prononcé en français: /lu.ka.ʃɛn.ko/; en biélorusse: Аляксaндр Рыгoравіч Лукашэнка /alʲaˈksandr rɨˈɣɔravʲitʂ lukaˈʂɛnka/, en russe: Александр Григорьевич Лукашенко /ɐlʲɪˈksandr ɡrʲɪˈɡorʲjɪvʲɪtɕ ɫʊkɐˈʂɛnkə/), né le 30 août 1954 à Kopys, est un homme d'État biélorusse, président de la République depuis 1994.",119,"fr:Alexandre_Loukachenko","c:f/fe/%D0%90%D0%BB%D0%B5%D0%BA%D1%81%D0%B0%D0%BD%D0%B4%D1%80_%D0%9B%D1%83%D0%BA%D0%B0%D1%88%D0%B5%D0%BD%D0%BA%D0%BE_%2813-04-2023%29_%28cropped%29.jpg"],["Q155979",7,"politicien","Alexeï Navalny","PC","Alexeï Anatolievitch Navalny, né le 4 juin 1976 à Boutyne dans l'oblast de Moscou et mort le 16 février 2024 au centre pénitentiaire de Kharp en Iamalie, est un avocat, militant anticorruption, homme politique et prisonnier politique russe. Il organise des manifestations et plaide en faveur de réformes contre la corruption en Russie et le régime de Vladimir Poutine.",118,"fr:Alexeï_Navalny","c:d/db/Alexey_Navalny_2018_%28cropped%29.png"],["Q57336",8,"politicien","Ali Khamenei","R","Ali Khamenei, né le 19 avril 1939 à Machhad et tué lors d'une frappe aérienne américano-israélienne le 28 février 2026 à Téhéran, est un ayatollah et homme d'État iranien, Guide suprême de 1989 à sa mort. Il est président de la république islamique d'Iran de 1981 à 1989.",118,"fr:Ali_Khamenei","c:e/e2/Ali_Khamenei_Nowruz_message_official_portrait_1397_02.jpg"],["Q11817",9,"politicien","Andrew Jackson","R","Andrew Jackson, né le 15 mars 1767 à Waxhaws et mort le 8 juin 1845 à Nashville, est un militaire, planteur esclavagiste et homme d'État américain. Il est le 7e président des États-Unis, en fonction du 4 mars 1829 au 4 mars 1837, et le premier issu du Parti démocrate.",107,"fr:Andrew_Jackson","c:4/43/Andrew_jackson_head.jpg",{"cats":["politique","usa"]}],["Q8612",10,"politicien","Andrew Johnson","C","Andrew Johnson, né le 29 décembre 1808 à Raleigh et mort le 31 juillet 1875 à Elizabethton, est un homme d'État américain. Membre du Parti démocrate, il est le 16e vice-président des États-Unis, en fonction du 4 mars au 15 avril 1865, puis le 17e président des États-Unis, en fonction du 15 avril 1865 au 4 mars 1869.",111,"fr:Andrew_Johnson","c:e/e6/Andrew_Johnson_photo_portrait_head_and_shoulders%2C_c1870-1880-Edit1.jpg"],["Q567",11,"politicien","Angela Merkel","PC","Angela Merkel (/ˈaŋɡela ˈmɛʁkl/), née Angela Kasner le 17 juillet 1954 à Hambourg, est une femme d'État allemande. Membre de l'Union chrétienne-démocrate, elle est chancelière fédérale d'Allemagne du 22 novembre 2005 au 8 décembre 2021.","Angela Merkel (/ˈaŋɡela ˈmɛʁkl/), née Angela Kasner le 17 juillet 1954 à Hambourg, est une femme d'État allemande.","fr:Angela_Merkel","c:f/f3/Angela_Merkel_2023_%28cropped_2%29.jpg"],["Q8589",13,"politicien","Ashoka","C","Ashoka ou Aśoka, né vers 304 av. J.-C. et mort en 232 av. J.-C., est le troisième empereur de la dynastie indienne des Maurya.","Ashoka ou Aśoka, né vers 304 av.","fr:Ashoka","c:2/28/Ashoka%27s_visit_to_the_Ramagrama_stupa_Sanchi_Stupa_1_Southern_gateway.jpg"],["Q36740",15,"politicien","Aung San Suu Kyi","C","Daw Aung San Suu Kyi, née le 19 juin 1945 à Rangoun, est une femme d'État birmane. Figure de l'opposition non violente à la dictature militaire de son pays, lauréate du prix Nobel de la paix en 1991, elle est de facto chef du gouvernement de 2016 à 2021.","Daw Aung San Suu Kyi, née le 19 juin 1945 à Rangoun, est une femme d'État birmane.","fr:Aung_San_Suu_Kyi","c:6/6c/Remise_du_Prix_Sakharov_%C3%A0_Aung_San_Suu_Kyi_Strasbourg_22_octobre_2013-18.jpg"],["Q44329",16,"politicien","Bachar el-Assad","PC","Bachar el-Assad, également orthographié Bachar al-Assad, né le 11 septembre 1965 à Damas, est un homme d'État syrien, président de la République arabe syrienne du 17 juillet 2000 au 8 décembre 2024.",117,"fr:Bachar_el-Assad","c:7/77/Bashar_al-Assad_%282018-05-17%29_02_%28cropped%29.jpg"],["Q76",18,"politicien","Barack Obama","L","Barack Obama, né le 4 août 1961 à Honolulu, est un homme d'État américain. Membre du Parti démocrate, il est le 44e président des États-Unis, en fonction du 20 janvier 2009 au 20 janvier 2017.","Barack Obama, né le 4 août 1961 à Honolulu, est un homme d'État américain.","fr:Barack_Obama","c:8/8d/President_Barack_Obama.jpg",{"cats":["politique","usa"]}],["Q34413",20,"politicien","Benazir Bhutto","C","Benazir Bhutto, née le 21 juin 1953 à Karachi et morte assassinée le 27 décembre 2007 à Rawalpindi, est une femme d'État pakistanaise. Elle est Première ministre de 1988 à 1990 et de 1993 à 1996.",113,"fr:Benazir_Bhutto","c:c/c4/Oliver_Mark_-_Benazir_Bhutto%2C_Dubai_2006_%28cropped%29.jpg"],["Q82006",22,"politicien","Benjamin Disraeli","C","Benjamin Disraeli, né le 21 décembre 1804 et mort le 19 avril 1881 à Londres, est un homme d'État et écrivain britannique, Premier ministre du Royaume-Uni à deux reprises. Il joue un rôle central dans la création du Parti conservateur moderne dont il formalise la doctrine. Par sa grande influence sur la politique étrangère, il a associé les conservateurs à la gloire et à la puissance de l'Empire britannique.",109,"fr:Benjamin_Disraeli","c:0/0c/Benjamin_Disraeli_by_Cornelius_Jabez_Hughes%2C_1878.jpg"],["Q35678",24,"politicien","Benjamin Harrison","C","Benjamin Harrison, né le 20 août 1833 à North Bend et mort le 13 mars 1901 à Indianapolis, est un homme d'État américain. Membre du Parti républicain, il est le 23e président des États-Unis, en fonction du 4 mars 1889 au 4 mars 1893.",110,"fr:Benjamin_Harrison","c:f/f8/Benjamin_Harrison%2C_head_and_shoulders_bw_photo%2C_1896.jpg"],["Q43723",25,"politicien","Benyamin Netanyahou","M","Benyamin Netanyahou, né le 21 octobre 1949 à Tel Aviv, est un homme d'État israélien. Président du Likoud, parti sioniste national-conservateur, il est Premier ministre d'Israël de 1996 à 1999, de 2009 à 2021 et de nouveau depuis 2022.","Benyamin Netanyahou, né le 21 octobre 1949 à Tel Aviv, est un homme d'État israélien.","fr:Benyamin_Netanyahou","c:7/74/Benjamin_Netanyahu%2C_February_2023.jpg"],["Q359442",26,"politicien","Bernie Sanders","R","Bernard Sanders, dit Bernie Sanders, né le 8 septembre 1941 à New York, est un homme politique américain.",null,"fr:Bernie_Sanders","c:c/c2/Bernie_Sanders_February_2026_%28cropped%29.jpg"],["Q1124",27,"politicien","Bill Clinton","E","William Clinton, dit Bill Clinton, né le 19 août 1946 à Hope, est un homme d'État américain. Membre du Parti démocrate, il est le 42e président des États-Unis, en fonction du 20 janvier 1993 au 20 janvier 2001.","William Clinton, dit Bill Clinton, né le 19 août 1946 à Hope, est un homme d'État américain.","fr:Bill_Clinton","c:d/d3/Bill_Clinton.jpg",{"cats":["politique","usa"]}],["Q34453",28,"politicien","Boris Eltsine","PC","Boris Nikolaïevitch Eltsine ou Ieltsine, né le 1er février 1931 à Boutka et mort le 23 avril 2007 à Moscou, est un homme d'État russe, président de la fédération de Russie du 10 juillet 1991 au 31 décembre 1999.",114,"fr:Boris_Eltsine","c:8/86/Boris_Yeltsin_%283x4_cropped%29.jpg"],["Q180589",29,"politicien","Boris Johnson","PC","Alexander Boris de Pfeffel Johnson, dit Boris Johnson, né le 19 juin 1964 à New York, est un homme d'État britannique. Il est chef du Parti conservateur et Premier ministre du Royaume-Uni de 2019 à 2022.","Alexander Boris de Pfeffel Johnson, dit Boris Johnson, né le 19 juin 1964 à New York, est un homme d'État britannique.","fr:Boris_Johnson","c:7/76/Boris_Johnson_official_portrait_%28cropped%29.jpg"],["Q36023",30,"politicien","Calvin Coolidge","PC","Calvin Coolidge, né le 4 juillet 1872 à Plymouth et mort le 5 janvier 1933 à Northampton, est un homme d'État américain. Membre du Parti républicain, il est le 29e vice-président des États-Unis, en fonction du 4 mars 1921 au 2 août 1923, puis le 30e président des États-Unis, en fonction du 2 août 1923 au 4 mars 1929.","Calvin Coolidge, né le 4 juillet 1872 à Plymouth et mort le 5 janvier 1933 à Northampton, est un homme d'État américain.","fr:Calvin_Coolidge","c:4/49/President_Calvin_Coolidge%2C_1924_portrait_photograph_%283x4_cropped%29.jpeg"],["Q36450",31,"politicien","Catherine II","R","Catherine II ou Catherine la Grande, née Sophie Frédérique Augusta d'Anhalt-Zerbst le 2 mai 1729 à Stettin en Poméranie et morte le 17 novembre 1796 à Saint-Pétersbourg, est l'épouse de l'empereur Pierre III. Elle devient impératrice régnante de Russie, du 9 juillet 1762 à sa mort le 17 novembre 1796, à la suite d'un coup d'État contre Pierre III, incarcéré puis exécuté le 17 juillet sur les ordres de Catherine.",119,"fr:Catherine_II","c:7/72/Catherine_II_after_Roslin%2C_Rokotov_%281780s%2C_Kunsthistorisches_Museum%29.jpg"],["Q43274",33,"politicien","Charles III","L","Charles III, né le 14 novembre 1948 au palais de Buckingham, est roi du Royaume-Uni de Grande-Bretagne et d'Irlande du Nord ainsi que de quatorze autres États souverains, appelés royaumes du Commonwealth, et de leurs territoires et dépendances, depuis le 8 septembre 2022. En tant que monarque du Royaume-Uni, il est, de droit, gouverneur suprême de l'Église d'Angleterre et, par tradition, chef du Commonwealth, une organisation intergouvernementale regroupant cinquante-six États.",118,"fr:Charles_III_(roi_du_Royaume-Uni)","c:a/ac/King_Charles_III_%28July_2023%29.jpg"],["Q5809",35,"politicien","Che Guevara","E","Ernesto Rafael Guevara De La Serna, simplement nommé Ernesto Guevara et plus connu sous le nom de « Che Guevara » (/ʃe ɡevaʁa/; en espagnol: /t͡ʃe ɡeˈβaɾa/) ou « le Che », né le 14 juin 1928 d'après son acte de naissance à Rosario et mort exécuté le 9 octobre 1967 à La Higuera, est un révolutionnaire marxiste-léniniste et internationaliste argentin ainsi qu'un homme politique d'Amérique latine.",118,"fr:Che_Guevara","c:5/58/CheHigh.jpg"],["Q35498",36,"politicien","Chester A. Arthur","C","Chester Alan Arthur, généralement appelé Chester A. Arthur, né le 5 octobre 1829 à Fairfield et mort le 18 novembre 1886 à New York, est un homme d'État américain. Membre du Parti républicain, il est le 20e vice-président des États-Unis, en fonction du 4 mars au 19 septembre 1881, puis le 21e président des États-Unis, en fonction du 19 septembre 1881 au 4 mars 1885.","Chester Alan Arthur, généralement appelé Chester A.","fr:Chester_A._Arthur","c:4/48/20_Chester_Arthur_3x4.jpg"],["Q8413",38,"politicien","Constantin Ier","PC","Constantin Ier, né le 27 février 272 à Naissus en Mésie supérieure et mort le 22 mai 337 près de Nicomédie, dans la Province Romaine de Bithynie et Pont, est un empereur romain majeur du IVe siècle.",115,"fr:Constantin_Ier_(empereur_romain)","c:6/60/0_Gaius_Flavius_Valerius_Constantinus%2C_Palatino.jpg"],["Q37610",39,"politicien","David Ben Gourion","PC","David Ben Gourion, né David Grün, né le 16 octobre 1886 à Płońsk et mort le 1er décembre 1973 au kibboutz de Sde Boker, est un homme d'État israélien.",119,"fr:David_Ben_Gourion","c:e/e8/David_Ben-Gurion_%28D597-087%29.jpg"],["Q192",40,"politicien","David Cameron","C","David Cameron /ˈdeɪvɪd ˈkæmɹən/, baron Cameron de Chipping Norton, né le 9 octobre 1966 à Marylebone, est un homme d'État britannique. Membre du Parti conservateur, il est Premier ministre du Royaume-Uni du 11 mai 2010 au 13 juillet 2016 et secrétaire d'État aux Affaires étrangères, du Commonwealth et du Développement du 13 novembre 2023 au 5 juillet 2024.",114,"fr:David_Cameron","c:d/db/David_Cameron_Official_Portrait_2023_%28cropped%29.jpg"],["Q16977",41,"politicien","Deng Xiaoping","PC","Deng Xiaoping, né le 22 août 1904 à Guang'an et mort le 19 février 1997 à Pékin, est un homme d’État chinois. Il est Président de la Commission militaire centrale du Parti communiste chinois de juin 1981 à novembre 1989 et officieusement le numéro un de la république populaire de Chine de décembre 1978 à juin 1989. Deng Xiaoping est généralement considéré comme étant à l’origine du développement économique de la Chine actuelle. Il est largement connu comme « l'architecte en chef de la réforme et ouverture ».","Deng Xiaoping, né le 22 août 1904 à Guang'an et mort le 19 février 1997 à Pékin, est un homme d’État chinois.","fr:Deng_Xiaoping","c:d/dd/Deng_Xiaoping_at_the_arrival_ceremony_for_the_Vice_Premier_of_China_%28cropped%29.jpg"],["Q40722",42,"politicien","Dilma Rousseff","R","Dilma Vana Rousseff (/ˈd͡ʒiwmɐ ˈvanɐ ʁuˈsɛf/), née le 14 décembre 1947 à Belo Horizonte, est une économiste et femme d'État brésilienne. Membre du Parti des travailleurs, elle est présidente de la république fédérative du Brésil du 1er janvier 2011 au 31 août 2016.",116,"fr:Dilma_Rousseff","c:8/81/Dilma_Rousseff_-_foto_oficial_2011-01-09.jpg"],["Q23530",43,"politicien","Dmitri Medvedev","PC","Dmitri Medvedev, de son nom complet Dimitri Anatolievitch Medvedev, né le 14 septembre 1965 à Léningrad, est un homme d'État russe, Président de la Fédération de Russie de 2008 à 2012 et actuellement vice-président de Conseil de sécurité de Russie depuis 2020.",117,"fr:Dmitri_Medvedev","c:7/75/Dmitry_Medvedev_%282026-02-06%29.jpg"],["Q22686",44,"politicien","Donald Trump","M","Donald Trump, né le 14 juin 1946 à New York, est un homme d'affaires milliardaire, animateur, producteur de télévision et homme d'État américain. Membre du Parti républicain, il est le 45e et 47e président des États-Unis, en fonction du 20 janvier 2017 au 20 janvier 2021 et depuis le 20 janvier 2025.",118,"fr:Donald_Trump","c:1/16/Official_Presidential_Portrait_of_President_Donald_J._Trump_%282025%29.jpg",{"cats":["politique","usa"]}],["Q9916",45,"politicien","Dwight D. Eisenhower","E","Dwight David Eisenhower, généralement appelé « Le Général » Dwight D. Eisenhower et surnommé Ike, né le 14 octobre 1890 à Denison et mort le 28 mars 1969 à Washington, D.C., est un militaire et homme d'État américain. Membre du Parti républicain, il est le 34e président des États-Unis, en fonction du 20 janvier 1953 au 20 janvier 1961.","Dwight David Eisenhower, généralement appelé « Le Général » Dwight D.","fr:Dwight_D._Eisenhower","c:6/63/Dwight_D._Eisenhower%2C_official_photo_portrait%2C_May_29%2C_1959.jpg"],["Q83396",46,"politicien","Eleanor Roosevelt","PC","Anna Eleanor Roosevelt, née le 11 octobre 1884 et morte le 7 novembre 1962, est une figure politique, diplomate et militante américaine. Elle est également l'épouse de Franklin Delano Roosevelt. Par cette union, elle est la Première dame des États-Unis du 4 mars 1933 au 12 avril 1945. Elle est la première à donner une dimension politique et médiatique affirmée à ce rôle.",114,"fr:Eleanor_Roosevelt","c:c/cb/Eleanor_Roosevelt_at_the_United_Nations%2C_circa_1946-1947_%28cropped%29.jpg",{"cats":["politique","usa"]}],["Q3052772",48,"politicien","Emmanuel Macron","L","Emmanuel Macron, né le 21 décembre 1977 à Amiens, est un homme d'État français. Il est le président de la République française depuis le 14 mai 2017.","Emmanuel Macron, né le 21 décembre 1977 à Amiens, est un homme d'État français.","fr:Emmanuel_Macron","c:3/3c/Emmanuel_Macron_2025_%28cropped%29.jpg",{"cats":["politique","politique_fr"]}],["Q1463",49,"politicien","Ferdinand Marcos","C","Ferdinand Emmanuel Edralin Marcos, né le 11 septembre 1917 à Sarrat et mort le 28 septembre 1989 à Honolulu, est un avocat et homme d'État philippin, président des Philippines du 30 décembre 1965 au 25 février 1986 et Premier ministre de 1978 à 1981.",115,"fr:Ferdinand_Marcos","c:a/ab/Ferdinand-Marcos-speech.jpg"],["Q11256",50,"politicien","Fidel Castro","R","Fidel Castro ou Fidel Alejandro Castro Ruz, né le 13 août 1926 à Birán et mort le 25 novembre 2016 à La Havane, est un révolutionnaire et homme d'État cubain. Il dirige la république de Cuba, pendant 49 ans, comme Premier ministre de 1959 à 1976 et ensuite comme président du Conseil d'État et président du Conseil des ministres de 1976 à 2008. C'est son frère Raúl Castro qui lui succède.",118,"fr:Fidel_Castro","c:4/4a/Fidel_Castro_1950s.jpg"],["Q29179",52,"politicien","Francisco Franco","R","Francisco Franco Bahamonde, né le 4 décembre 1892 à Ferrol et mort le 20 novembre 1975 à Madrid, est un militaire et homme d'État espagnol. Chef du camp nationaliste à partir de 1936 pendant la guerre civile espagnole, il établit en Espagne, après la victoire franquiste en 1939, un régime dictatorial nommé État espagnol, qu'il dirige jusqu'à sa mort.",116,"fr:Francisco_Franco","c:c/cf/RETRATO_DEL_GRAL._FRANCISCO_FRANCO_BAHAMONDE_%28adjusted_levels%29.jpg"],["Q12312",53,"politicien","Franklin Pierce","C","Franklin Pierce, né le 23 novembre 1804 à Hillsborough et mort le 8 octobre 1869 à Concord, est un homme d'État américain. Membre du Parti démocrate, il est le 14e président des États-Unis, en fonction du 4 mars 1853 au 4 mars 1857. Pierce préside les États-Unis à une époque où la question de l'esclavage déchire le pays.",111,"fr:Franklin_Pierce","c:2/29/Franklin_Pierce.jpg"],["Q157",54,"politicien","François Hollande","E","François Hollande, né le 12 août 1954 à Rouen, est un haut fonctionnaire et homme d'État français. Il est président de la République française du 15 mai 2012 au 14 mai 2017.","François Hollande, né le 12 août 1954 à Rouen, est un haut fonctionnaire et homme d'État français.","fr:François_Hollande","c:f/fd/Fran%C3%A7ois_Hollande_-_Ceremony_of_Honour_for_Jacques_Delors_-_2024.jpg",{"cats":["politique","politique_fr"]}],["Q2038",55,"politicien","François Mitterrand","E","François Mitterrand, né le 26 octobre 1916 à Jarnac et mort le 8 janvier 1996 dans le 7e arrondissement de Paris, est un homme d'État français. Il est président de la République française du 21 mai 1981 au 17 mai 1995.",117,"fr:François_Mitterrand","c:4/4e/President_Mitterand_bij_slotzitting_Europa_Congres_Mitterand%2C_kop%2C_Bestanddeelnr_934-2444_%28portrait_crop%29.jpg",{"cats":["politique","politique_fr"]}],["Q30339350",56,"politicien","Gabriel Attal","E","Gabriel Attal, né le 16 mars 1989 à Clamart, est un homme d'État français, Premier ministre du 9 janvier au 5 septembre 2024. Redevenu député, il est depuis juillet 2024 président du groupe Ensemble pour la République à l'Assemblée nationale et est élu en décembre 2024 secrétaire général du parti Renaissance.",119,"fr:Gabriel_Attal","c:c/c4/Gabriel_Attal_2025_%28close_crop%29.jpg",{"cats":["politique","politique_fr"]}],["Q23505",57,"politicien","George H. W. Bush","R","George Herbert Walker Bush, généralement appelé George H. W. Bush ou simplement George Bush, voire George Bush père, né le 12 juin 1924 à Milton et mort le 30 novembre 2018 à Houston, est un homme d'État américain. Membre du Parti républicain, il est le 43e vice-président des États-Unis, en fonction du 20 janvier 1981 au 20 janvier 1989, puis le 41e président des États-Unis, en fonction du 20 janvier 1989 au 20 janvier 1993.","George Herbert Walker Bush, généralement appelé George H.","fr:George_H._W._Bush","c:e/ee/George_H._W._Bush_presidential_portrait_%28cropped%29.jpg"],["Q207",58,"politicien","George W. Bush","L","George Walker Bush, généralement appelé George W. Bush et parfois George Bush fils, né le 6 juillet 1946 à New Haven, est un homme d'État américain. Membre du Parti républicain, il est le 43e président des États-Unis, en fonction du 20 janvier 2001 au 20 janvier 2009.","George Walker Bush, généralement appelé George W.","fr:George_W._Bush","c:d/d4/George-W-Bush.jpeg",{"cats":["politique","usa"]}],["Q23",59,"politicien","George Washington","E","George Washington, né le 22 février 1732 à Pope's Creek et mort le 14 décembre 1799 à Mount Vernon, est un militaire, planteur esclavagiste et homme d'État américain. Après avoir été commandant en chef de l'Armée continentale pendant la guerre d'indépendance entre 1775 et 1783, il est le 1er président des États-Unis, en fonction du 30 avril 1789 au 4 mars 1797.",117,"fr:George_Washington","c:b/b6/Gilbert_Stuart_Williamstown_Portrait_of_George_Washington.jpg",{"cats":["politique","usa"]}],["Q171730",60,"politicien","Georges Clemenceau","C","Georges Clemenceau, né le 28 septembre 1841 à Mouilleron-en-Pareds et mort le 24 novembre 1929 à Paris, est un homme d'État français, président du Conseil de 1906 à 1909 puis de 1917 à 1920.",116,"fr:Georges_Clemenceau","c:c/c7/Georges_Clemenceau_par_Nadar.jpg"],["Q2185",61,"politicien","Georges Pompidou","R","Georges Pompidou, né le 5 juillet 1911 à Montboudif et mort le 2 avril 1974 dans le 4e arrondissement de Paris, est un homme d'État français. Il est Premier ministre du 14 avril 1962 au 10 juillet 1968 et président de la République française du 20 juin 1969 jusqu'à sa mort.",118,"fr:Georges_Pompidou","c:2/2a/Georges_Pompidou_1969_%28cropped%29.jpg",{"cats":["politique","politique_fr"]}],["Q9582",62,"politicien","Gerald Ford","PC","Gerald Ford, né le 14 juillet 1913 à Omaha et mort le 26 décembre 2006 à Rancho Mirage, est un homme d'État américain. Membre du Parti républicain, il est le 40e vice-président des États-Unis, en fonction du 6 décembre 1973 au 9 août 1974, puis le 38e président des États-Unis, en fonction du 9 août 1974 au 20 janvier 1977.","Gerald Ford, né le 14 juillet 1913 à Omaha et mort le 26 décembre 2006 à Rancho Mirage, est un homme d'État américain.","fr:Gerald_Ford","c:3/36/Gerald_Ford_presidential_portrait_%28cropped%29.jpg"],["Q42992",64,"politicien","Golda Meir","PC","Golda Meir, née Golda Mabovitch à Kiev le 3 mai 1898 et morte à Jérusalem le 8 décembre 1978, est une femme d'État israélienne. Elle participe à la création de l'État d'Israël, a été ministre des Affaires étrangères, ainsi que la quatrième Première ministre d'Israël du 17 mars 1969 au 11 avril 1974.",114,"fr:Golda_Meir","c:2/24/Golda_Meir_03265u-2.jpg"],["Q35171",65,"politicien","Grover Cleveland","PC","Grover Cleveland, né le 18 mars 1837 à Caldwell et mort le 24 juin 1908 à Princeton, est un homme d'État américain. Membre du Parti démocrate, il est le 22e et 24e président des États-Unis, en fonction du 4 mars 1885 au 4 mars 1889 et du 4 mars 1893 au 4 mars 1897.","Grover Cleveland, né le 18 mars 1837 à Caldwell et mort le 24 juin 1908 à Princeton, est un homme d'État américain.","fr:Grover_Cleveland","c:3/36/StephenGroverCleveland.jpg"],["Q4414537",66,"politicien","Guillermo Lasso","C","Guillermo Lasso Mendoza, né le 16 novembre 1955 à Guayaquil, est un homme d'affaires et homme d'État équatorien. Il est président de la république de l'Équateur du 24 mai 2021 au 23 novembre 2023.","Guillermo Lasso Mendoza, né le 16 novembre 1955 à Guayaquil, est un homme d'affaires et homme d'État équatorien.","fr:Guillermo_Lasso","c:c/cf/President_Guillermo_Lasso_2022.jpg"],["Q36456",68,"politicien","Hannibal Barca","PC","Hannibal Barca, généralement appelé Annibal ou Hannibal, né en 247 av. J.-C. à Carthage et mort entre 183 et 181 av. J.-C. en Bithynie, est un général et homme politique carthaginois, considéré comme l'un des plus grands tacticiens militaires de l'Histoire.","Hannibal Barca, généralement appelé Annibal ou Hannibal, né en 247 av.","fr:Hannibal_Barca","c:b/b4/Hannibal_Barca_bust_from_Capua_photo.jpg"],["Q11613",69,"politicien","Harry S. Truman","R","Harry S. Truman, parfois appelé simplement Harry Truman, né le 8 mai 1884 à Lamar et mort le 26 décembre 1972 à Kansas City, est un homme d'État américain. Membre du Parti démocrate, il est le 34e vice-président des États-Unis, en fonction du 20 janvier au 12 avril 1945, puis le 33e président des États-Unis, en fonction du 12 avril 1945 au 20 janvier 1953. Truman préside les États-Unis pendant la fin de la Seconde Guerre mondiale et la montée des tensions avec l'Union soviétique dans le cadre de la guerre froide.","Harry S.","fr:Harry_S._Truman","c:0/0b/TRUMAN_58-766-06_%28cropped%29.jpg"],["Q66107",70,"politicien","Henry Kissinger","R","Henry Kissinger, né Heinz Alfred Kissinger le 27 mai 1923 à Fürth en Allemagne et mort le 29 novembre 2023 à Kent, est un diplomate américain, politologue et consultant en géopolitique.",118,"fr:Henry_Kissinger","c:3/3a/Henry_Kissinger_Shankbone_Metropolitan_Opera_2009.jpg"],["Q35236",71,"politicien","Herbert Hoover","PC","Herbert Hoover, né le 10 août 1874 à West Branch et mort le 20 octobre 1964 à New York, est un homme d'État américain. Membre du Parti républicain, il est le 31e président des États-Unis, en fonction du 4 mars 1929 au 4 mars 1933. La quasi-totalité de sa présidence est marquée par la Grande Dépression.","Herbert Hoover, né le 10 août 1874 à West Branch et mort le 20 octobre 1964 à New York, est un homme d'État américain.","fr:Herbert_Hoover","c:5/57/President_Hoover_portrait.jpg"],["Q6294",72,"politicien","Hillary Clinton","R","Hillary Diane Rodham Clinton /ˈhɪləɹi daɪˈæn ˈklɪntən/, née Rodham /ˈɹɑdəm/ le 26 octobre 1947 à Chicago, est une femme politique américaine.",119,"fr:Hillary_Clinton","c:2/27/Hillary_Clinton_official_Secretary_of_State_portrait_crop.jpg",{"cats":["politique","usa"]}],["Q34105",73,"politicien","Hosni Moubarak","C","Hosni Moubarak, né Mohammed Hosni El Sayed Moubarak le 4 mai 1928 à Kafr-el-Meselha et mort le 25 février 2020 au Caire, est un homme d'État égyptien. Il est président de la république arabe d'Égypte du 14 octobre 1981 au 11 février 2011, après avoir succédé à Anouar el-Sadate, dont il était le vice-président au moment de son assassinat.",113,"fr:Hosni_Moubarak","c:8/89/Hosni_Mubarak_-_Official_Photo.JPG"],["Q8440",74,"politicien","Hugo Chávez","C","Hugo Chávez Frías, né le 28 juillet 1954 à Sabaneta et mort le 5 mars 2013 à Caracas, est un militaire et homme d'État vénézuélien. Il est président de la république bolivarienne du Venezuela du 2 février 1999 jusqu'à sa mort.",118,"fr:Hugo_Chávez","c:9/9f/Hugo_Ch%C3%A1vez_%2802-04-2010%29.jpg"],["Q36014",75,"politicien","Hô Chi Minh","PC","Hồ Chí Minh, né Nguyễn Sinh Cung le 19 mai 1890 à Hoàng Trù et mort le 2 septembre 1969 à Hanoï, est un homme d'État vietnamien et une figure importante de l'anticolonialisme,du nationalisme vietnamien et du communisme international.",116,"fr:Hô_Chi_Minh","c:0/07/Ho_Chi_Minh_-_1946_Portrait.jpg"],["Q1149",76,"politicien","Indira Gandhi","PC","Indira Priyadarshini Gandhi, née Nehru le 19 novembre 1917 à Prayagraj, et morte assassinée le 31 octobre 1984 à New Delhi, est une femme d'État indienne. Elle est Première ministre de l'Inde de 1966 à 1977, puis de 1980 à sa mort en 1984.",116,"fr:Indira_Gandhi","c:f/fd/Prime_Minister_Indira_Gandhi_in_the_US_enhanced.jpg"],["Q2105",77,"politicien","Jacques Chirac","E","Jacques Chirac, né le 29 novembre 1932 dans le 5e arrondissement de Paris et mort le 26 septembre 2019 dans le 6e arrondissement de la même ville, est un homme d'État français. Il est Premier ministre du 27 mai 1974 au 25 août 1976 et du 20 mars 1986 au 10 mai 1988, et président de la République française du 17 mai 1995 au 16 mai 2007.",113,"fr:Jacques_Chirac","c:7/7b/Jacques_Chirac_%281997%29_%28cropped%29.jpg",{"cats":["politique","politique_fr"]}],["Q153425",78,"politicien","Jacques Delors","C","Jacques Delors, né le 20 juillet 1925 à Paris et mort le 27 décembre 2023 dans la même ville, est un homme politique français.",116,"fr:Jacques_Delors","c:4/41/Jacques_Delors_%281993%29_%28cropped%29.jpg"],["Q10304982",79,"politicien","Jair Bolsonaro","M","Jair Messias Bolsonaro, né le 21 mars 1955 à Glicério, est un militaire et homme d'État brésilien d'extrême droite. Après avoir été député fédéral de Rio de Janeiro pendant vingt-huit ans pour des partis de droite conservatrice, il est président de la République du 1er janvier 2019 au 1er janvier 2023.","Jair Messias Bolsonaro, né le 21 mars 1955 à Glicério, est un militaire et homme d'État brésilien d'extrême droite.","fr:Jair_Bolsonaro","c:8/8a/Jair_Bolsonaro_em_24_de_abril_de_2019_%281%29_%28cropped%29.jpg"],["Q34597",80,"politicien","James A. Garfield","PC","James Abram Garfield, généralement appelé James A. Garfield, né le 19 novembre 1831 à Orange et mort le 19 septembre 1881 à Elberon des suites de ses blessures après une tentative d'assassinat le 2 juillet 1881, est un homme d'État américain. Membre du Parti républicain, il est le 20e président des États-Unis, en fonction du 4 mars 1881 jusqu'à sa mort.","James Abram Garfield, généralement appelé James A.","fr:James_A._Garfield","c:1/1f/James_Abram_Garfield%2C_photo_portrait_seated.jpg"],["Q12325",81,"politicien","James Buchanan","PC","James Buchanan, né le 23 avril 1791 à Cove Gap et mort le 1er juin 1868 à Lancaster, est un diplomate et homme d'État américain. Membre du Parti démocrate, il est le 15e président des États-Unis, en fonction du 4 mars 1857 au 4 mars 1861. Démocrate du nord, il est reconnu pour sa défense des droits des États, notamment en matière d'esclavage et d'avoir minimisé le rôle du gouvernement fédéral dans les années précédant la guerre de Sécession.",117,"fr:James_Buchanan","c:f/fd/James_Buchanan.jpg"],["Q11891",82,"politicien","James K. Polk","C","James Knox Polk, généralement appelé James K. Polk, né le 2 novembre 1795 à Pineville et mort le 15 juin 1849 à Nashville, est un homme d'État américain. Membre du Parti démocrate, il est le 11e président des États-Unis, en fonction du 4 mars 1845 au 4 mars 1849. Sa présidence est marquée par une vaste expansion territoriale des États-Unis, qui permet au pays de s'étendre jusqu'à l'océan Pacifique.","James Knox Polk, généralement appelé James K.","fr:James_K._Polk","c:4/46/James_Polk_restored_%26_cropped.jpg"],["Q11813",83,"politicien","James Madison","PC","James Madison, né le 16 mars 1751 à Port Conway et mort le 28 juin 1836 à Montpelier, est un théoricien politique et homme d'État américain. Membre du Parti républicain-démocrate, il est le 4e président des États-Unis, en fonction du 4 mars 1809 au 4 mars 1817.",116,"fr:James_Madison","c:1/1d/James_Madison.jpg",{"cats":["politique","usa"]}],["Q11815",84,"politicien","James Monroe","C","James Monroe, né le 28 avril 1758 dans le comté de Westmoreland et mort le 4 juillet 1831 à New York, est un diplomate et homme d'État américain. Membre du Parti républicain-démocrate, il est le 5e président des États-Unis, en fonction du 4 mars 1817 au 4 mars 1825, et le dernier faisant partie des Pères fondateurs des États-Unis. Sa présidence est surtout connue pour la Doctrine Monroe, proclamée en 1823, qui affirme que les puissances européennes ne doivent plus intervenir sur le continent américain.",118,"fr:James_Monroe","c:d/d4/James_Monroe_White_House_portrait_1819.jpg"],["Q1047",85,"politicien","Jawaharlal Nehru","PC","Jawaharlal Nehru, également connu sous le nom de Pandit Nehru voire Panditji, né le 14 novembre 1889 à Prayagraj et mort le 27 mai 1964 à New Delhi, est un homme d'État indien. Il est l'une des figures de proue de la lutte pour l'indépendance de l'Inde et du Congrès national indien et devient le premier Premier ministre de l'Inde du 15 août 1947 jusqu'à sa mort.",115,"fr:Jawaharlal_Nehru","c:4/4d/Jawaharlal_Nehru_1957_crop.jpg"],["Q12688",86,"politicien","Jean Jaurès","C","Jean Jaurès né le 3 septembre 1859 à Castres et mort assassiné le 31 juillet 1914 à Paris, est un homme politique, journaliste, historien et philosophe français. D’abord républicain modéré, il évolue vers le socialisme au début des années 1890, notamment à l’occasion de la grève des mineurs de Carmaux de 1892. Il devient ensuite l’une des principales figures du socialisme français et œuvre à son unification.",114,"fr:Jean_Jaurès","c:8/8e/Jean_Jaur%C3%A8s%2C_1904%2C_by_Nadar.jpg"],["Q159700",87,"politicien","Jean Monnet","C","Jean Monnet, né le 9 novembre 1888 à Cognac et mort le 16 mars 1979 à Bazoches-sur-Guyonne, est un haut fonctionnaire français, banquier international, promoteur de l'atlantisme et du libre-échange. Europhile convaincu et acteur majeur de l'intégration et de la construction européennes, il est considéré comme l'un des « pères de l'Europe ».",117,"fr:Jean_Monnet","c:5/58/Jean_Monnet_1967.jpg"],["Q5829",88,"politicien","Jean-Luc Mélenchon","M","Jean-Luc Mélenchon, né le 19 août 1951 à Tanger au Maroc, est un homme politique français. Il est le fondateur et la figure principale du parti La France insoumise, souvent considéré comme relevant de la gauche radicale et classé à gauche, voire à l'extrême gauche.","Jean-Luc Mélenchon, né le 19 août 1951 à Tanger au Maroc, est un homme politique français.","fr:Jean-Luc_Mélenchon","c:3/3e/Jean_Luc_M%C3%A9lenchon_en_mai_2026-_55261894422_%28cropped%29.jpg",{"cats":["politique","politique_fr"]}],["Q23685",89,"politicien","Jimmy Carter","E","James Earl Carter, Jr., dit Jimmy Carter, né le 1er octobre 1924 à Plains et mort le 29 décembre 2024 dans la même ville, est un homme d'État américain. Membre du Parti démocrate, il est le 39e président des États-Unis, en fonction du 20 janvier 1977 au 20 janvier 1981.",114,"fr:Jimmy_Carter","c:6/6a/Jimmy_Carter_Official_Portrait2_%283x4_cropped%29.jpg",{"cats":["politique","usa"]}],["Q6279",90,"politicien","Joe Biden","E","Joe Biden, né le 20 novembre 1942 à Scranton, est un homme d'État américain. Membre du Parti démocrate, il est le 47e vice-président des États-Unis, en fonction du 20 janvier 2009 au 20 janvier 2017, puis le 46e président des États-Unis, en fonction du 20 janvier 2021 au 20 janvier 2025.","Joe Biden, né le 20 novembre 1942 à Scranton, est un homme d'État américain.","fr:Joe_Biden","c:6/68/Joe_Biden_presidential_portrait.jpg",{"cats":["politique","usa"]}],["Q11806",92,"politicien","John Adams","R","John Adams, né le 30 octobre 1735 à Braintree et mort le 4 juillet 1826 à Quincy, est un avocat, diplomate et homme d'État américain. Membre du Parti fédéraliste, il est le 1er vice-président des États-Unis, en fonction du 30 avril 1789 au 4 mars 1797, puis le 2e président des États-Unis, en fonction du 4 mars 1797 au 4 mars 1801.",115,"fr:John_Adams_(homme_d'État)","c:f/ff/Gilbert_Stuart%2C_John_Adams%2C_c._1800-1815%2C_NGA_42933.jpg",{"cats":["politique","usa"]}],["Q9696",93,"politicien","John Fitzgerald Kennedy","L","John Fitzgerald Kennedy, simplement nommé John F. Kennedy ou JFK, et également connu sous son surnom Jack Kennedy, né le 29 mai 1917 à Brookline et mort assassiné le 22 novembre 1963 à Dallas, est un homme d'État américain. Membre du Parti démocrate, il est le 35e président des États-Unis, en fonction du 20 janvier 1961 jusqu'à sa mort.","John Fitzgerald Kennedy, simplement nommé John F.","fr:John_Fitzgerald_Kennedy","c:c/c3/John_F._Kennedy%2C_White_House_color_photo_portrait.jpg",{"cats":["politique","usa"]}],["Q10390",94,"politicien","John McCain","PC","John Sidney McCain III, né le 29 août 1936 sur la base militaire américaine de Coco Solo et mort le 25 août 2018 à Cornville, est un vétéran de la guerre du Viêt Nam et homme politique américain. Il est sénateur de l'Arizona au Congrès des États-Unis de 1987 à sa mort et candidat républicain à l'élection présidentielle de 2008.",114,"fr:John_McCain","c:e/e1/John_McCain_official_portrait_2009.jpg"],["Q11816",95,"politicien","John Quincy Adams","PC","John Quincy Adams, né le 11 juillet 1767 à Braintree et mort le 23 février 1848 à Washington, D.C., est un diplomate et homme d'État américain. Il est le 6e président des États-Unis, en fonction du 4 mars 1825 au 4 mars 1829.",119,"fr:John_Quincy_Adams","c:f/f0/John_Q._Adams.jpg"],["Q50020",96,"politicien","John Stuart Mill","C","John Stuart Mill, né le 20 mai 1806 à Londres et mort le 8 mai 1873 à Avignon, est un philosophe, logicien et économiste britannique. Penseur libéral parmi les plus influents du XIXe siècle, il est un partisan de l'utilitarisme, une théorie éthique conçue par Jeremy Bentham.",109,"fr:John_Stuart_Mill","c:4/43/John_Stuart_Mill_by_John_Watkins%2C_1865.jpg"],["Q11881",97,"politicien","John Tyler","C","John Tyler, né le 29 mars 1790 dans la plantation Greenway et mort le 18 janvier 1862 à Richmond, est un homme d'État américain. Il est le 10e vice-président des États-Unis, en fonction du 4 mars au 4 avril 1841, puis le 10e président des États-Unis, en fonction du 4 avril 1841 au 4 mars 1845. À la mort du président William Henry Harrison, il devient le premier vice-président américain à accéder à la présidence, provoquant un événement constitutionnel sans précédent quant à la succession présidentielle.",117,"fr:John_Tyler","c:1/1c/Tyler%2C_John%2C_by_Healy_%281842%2C_NPG_2019_13%29.jpg"],["Q40655898",98,"politicien","Jordan Bardella","L","Jordan Bardella, né le 13 septembre 1995 à Drancy, est un homme politique français. Depuis 2021, il est président du Rassemblement national, principal parti d'extrême droite en France.","Jordan Bardella, né le 13 septembre 1995 à Drancy, est un homme politique français.","fr:Jordan_Bardella","c:1/13/MEP_Jordan_Bardella.jpg",{"cats":["politique","politique_fr"]}],["Q41749",99,"politicien","Joseph Goebbels","R","Joseph Goebbels, né le 29 octobre 1897 à Rheydt et mort par suicide le 1er mai 1945 à Berlin, est un homme d'État allemand et criminel nazi. Proche d'Adolf Hitler, il fut, avec Hermann Göring et Heinrich Himmler, l'un des dirigeants les plus puissants et influents du Troisième Reich.",113,"fr:Joseph_Goebbels","c:3/35/Bundesarchiv_Bild_146-1968-101-20A%2C_Joseph_Goebbels.jpg"],["Q855",100,"politicien","Joseph Staline","E","Joseph Staline, né le 18 décembre 1878 à Gori et mort le 5 mars 1953 à Moscou, est un révolutionnaire bolchévique et homme d'État soviétique d'origine géorgienne. Il dirige l'Union des républiques socialistes soviétiques à partir de la fin des années 1920 jusqu'à sa mort en établissant un régime de dictature personnelle absolue de type totalitaire. Les historiens le jugent responsable de la mort de quatre à dix millions de personnes, ou plus de vingt millions en tenant compte des famines.",116,"fr:Joseph_Staline","c:f/f7/Joseph_Stalin_official_portrait_%283x4_cropped%29.jpg"],["Q9161",101,"politicien","Josip Broz Tito","PC","Josip Broz Tito, né Josip Broz le 7 mai 1892 à Kumrovec et mort le 4 mai 1980 à Ljubljana, communément appelé « Tito » ou le maréchal Tito, est un homme d'État yougoslave. Il est la figure centrale de la Yougoslavie communiste, de 1945 à 1980.",118,"fr:Josip_Broz_Tito","c:1/13/Josip_Broz_Tito_uniform_portrait.jpg"],["Q3099714",103,"politicien","Justin Trudeau","PC","Justin Trudeau, né le 25 décembre 1971 à Ottawa, est un homme d'État canadien. Fils de l'ancien premier ministre Pierre Elliott Trudeau, il occupe à son tour le poste de premier ministre du Canada de 2015 à 2025.","Justin Trudeau, né le 25 décembre 1971 à Ottawa, est un homme d'État canadien.","fr:Justin_Trudeau","c:f/f3/Justin_Trudeau_at_the_European_Commission_-_2025.jpg"],["Q10853588",104,"politicien","Kamala Harris","R","Kamala Harris, née le 20 octobre 1964 à Oakland, est une femme d'État américaine. Membre du Parti démocrate, elle est la 49e vice-présidente des États-Unis — du 20 janvier 2021 au 20 janvier 2025 — et la première femme à exercer ces fonctions. Elle est la candidate officielle du Parti démocrate à l'élection présidentielle américaine de 2024.","Kamala Harris, née le 20 octobre 1964 à Oakland, est une femme d'État américaine.","fr:Kamala_Harris","c:4/41/Kamala_Harris_Vice_Presidential_Portrait.jpg",{"cats":["politique","usa"]}],["Q1254",108,"politicien","Kofi Annan","C","Kofi Annan, né le 8 avril 1938 à Kumasi et mort le 18 août 2018 à Berne, est un diplomate ghanéen.",null,"fr:Kofi_Annan","c:1/1a/Kofi_Annan.jpg"],["Q2492",109,"politicien","Konrad Adenauer","PC","Konrad Hermann Joseph Adenauer, né le 5 janvier 1876 à Cologne et mort le 19 avril 1967 à Rhöndorf, est un homme d'État allemand.",119,"fr:Konrad_Adenauer","c:c/c4/Konrad_Adenauer_Bouserath2.jpg"],["Q8620",110,"politicien","Kwame Nkrumah","C","Kwame Nkrumah, né le 21 septembre 1909 à Nkroful alors Côte-de-l'Or et actuel Ghana et mort le 27 avril 1972 à Bucarest, est un homme d'État indépendantiste et panafricaniste ghanéen. Il a dirigé la Côte-de-l'Or britannique de 1954 à 1957, puis le Ghana indépendant, d'abord comme Premier ministre de 1957 à 1960, puis en qualité de président de la République de 1960 à 1966.",110,"fr:Kwame_Nkrumah","c:2/21/Kwame_Nkrumah_-_The_National_Archives_UK_-_CO_1069-50-1-crop.jpg"],["Q444",111,"politicien","Lech Wałęsa","C","Lech Wałęsa, né le 29 septembre 1943 à Popowo, est un syndicaliste et homme d'État polonais. Cofondateur du mouvement Solidarność, il est président de la république de Pologne de 1990 à 1995.","Lech Wałęsa, né le 29 septembre 1943 à Popowo, est un syndicaliste et homme d'État polonais.","fr:Lech_Wałęsa","c:a/a8/Lech_Wa%C5%82%C4%99sa_1996.jpg"],["Q37181",113,"politicien","Luiz Inácio Lula da Silva","M","Luiz Inácio Lula da Silva, souvent appelé « Lula » ou « Lula da Silva », né le 27 octobre 1945 à Caetés, est un homme d'État brésilien. Figure historique du Parti des travailleurs, il est président de la république fédérative du Brésil de 2003 à 2011 et depuis 2023.",117,"fr:Luiz_Inácio_Lula_da_Silva","c:f/f3/Foto_oficial_de_Luiz_In%C3%A1cio_Lula_da_Silva_%282023%E2%80%932027%29.jpg"],["Q9640",114,"politicien","Lyndon B. Johnson","R","Lyndon Baines Johnson, généralement appelé Lyndon B. Johnson et également connu sous ses initiales LBJ, né le 27 août 1908 à Stonewall et mort le 22 janvier 1973 à Johnson City, était un homme d'État américain. Membre du Parti démocrate, il est le 37e vice-président des États-Unis, en fonction du 20 janvier 1961 au 22 novembre 1963, puis le 36e président des États-Unis, en fonction du 22 novembre 1963 au 20 janvier 1969.","Lyndon Baines Johnson, généralement appelé Lyndon B.","fr:Lyndon_B._Johnson","c:c/c4/Lyndon_B._Johnson%2C_photo_portrait%2C_color_%283x4_cropped%29.jpg"],["Q18434",115,"politicien","Léon Blum","C","Léon Blum, né le 9 avril 1872 à Paris 2e et mort le 30 mars 1950 à Jouy-en-Josas, est un homme d'État et conseiller d'État français. Figure du socialisme, il est président du Conseil de juin 1936 à juin 1937 et de mars à avril 1938, puis président du Gouvernement provisoire de la République française de décembre 1946 à janvier 1947.",115,"fr:Léon_Blum","c:2/23/L%C3%A9on_Blum.jpg"],["Q33391",116,"politicien","Léon Trotski","R","Léon Trotski, de son vrai nom Lev Davidovitch Bronstein, né le 26 octobre 1879 à Ianovka, une ville ukrainienne de l'Empire russe, et mort assassiné le 21 août 1940 à Mexico, est un idéologue, révolutionnaire bolchévique, théoricien politique communiste et homme politique russe puis soviétique.",114,"fr:Léon_Trotski","c:1/1f/%D0%9B%D0%B5%D0%B2_%D0%94%D0%B0%D0%B2%D0%B8%D0%B4%D0%BE%D0%B2%D0%B8%D1%87_%D0%A2%D1%80%D0%BE%D1%86%D0%BA%D0%B8%D0%B9.jpg"],["Q765165",117,"politicien","Léonid Brejnev","R","Léonid Ilitch Brejnev, né le 6 décembre 1906 à Kamenskoïe et mort le 10 novembre 1982 à Moscou, est un homme d'État soviétique d'origine ukrainienne, secrétaire général du Parti communiste de l'Union soviétique, et donc principal dirigeant de l'URSS de 1964 à 1982. Il fut en outre président du Præsidium du Soviet suprême à deux reprises, de 1960 à 1964 et de 1977 à 1982.",115,"fr:Léonid_Brejnev","c:b/b9/Leonid_Brezjnev%2C_leider_van_de_Sovjet-Unie%2C_Bestanddeelnr_925-6564.jpg"],["Q181383",118,"politicien","Mahathir Mohamad","C","Mahathir bin Mohamad, né le 10 juillet 1925 à Alor Setar, est un homme d'État malaisien, Premier ministre de 1981 à 2003 et de 2018 à 2020.",115,"fr:Mahathir_Mohamad","c:e/eb/Mahathir_Mohamad_13112018_%28cropped%29.jpg"],["Q34448",119,"politicien","Mahmoud Ahmadinejad","C","Mahmoud Ahmadinejad (en persan: محمود احمدی‌نژاد / Maḥmud Aḥmadi-Nežâd ), né le 28 octobre 1956 à Aradan près de Garmsar, est un homme d'État iranien, sixième président de la république islamique d'Iran de 2005 à 2013.",112,"fr:Mahmoud_Ahmadinejad","c:7/75/Mahmoud_Ahmadinejad_2019_02.jpg"],["Q43303",120,"politicien","Malcolm X","E","Malcolm X, né Malcolm Little, également nommé Al-Hâjj Mâlik al-Shabazz, né le 19 mai 1925 à Omaha et mort assassiné le 21 février 1965 à Harlem, est un orateur, prédicateur, porte-parole de Nation of Islam, militant politique et défenseur des droits de l'homme afro-américain.",118,"fr:Malcolm_X","c:5/54/Malcolm_X_1964_press_photo.jpg",{"cats":["politique","usa"]}],["Q7416",122,"politicien","Margaret Thatcher","R","Margaret Thatcher (), baronne Thatcher, née Margaret Roberts le 13 octobre 1925 à Grantham et morte le 8 avril 2013 à Londres, est une femme d'État britannique, Première ministre du Royaume-Uni du 4 mai 1979 au 28 novembre 1990.",117,"fr:Margaret_Thatcher","c:3/3d/Margaret_Thatcher_stock_portrait_%28cropped%29.jpg"],["Q12927",123,"politicien","Marine Le Pen","L","Marine Le Pen, née le 5 août 1968 à Neuilly-sur-Seine, est une femme politique française. Elle est la figure principale du Front national renommé Rassemblement national, le principal parti d'extrême droite en France, qu'elle dirige de 2011 à 2021.","Marine Le Pen, née le 5 août 1968 à Neuilly-sur-Seine, est une femme politique française.","fr:Marine_Le_Pen","c:8/81/Marine_Le_Pen_2025_%28cropped%29.jpg",{"cats":["politique","politique_fr"]}],["Q8027",124,"politicien","Martin Luther King","E","Martin Luther King Jr., né Michael King Jr., plus couramment appelé Martin Luther King, né à Atlanta, en Géorgie, le 15 janvier 1929, et mort assassiné le 4 avril 1968 à Memphis, dans le Tennessee, est un pasteur chrétien baptiste et militant non violent afro-américain pour le mouvement américain des droits civiques, fervent militant pour la paix et contre la pauvreté.",119,"fr:Martin_Luther_King","c:0/05/Martin_Luther_King%2C_Jr..jpg",{"cats":["politique","usa"]}],["Q11820",125,"politicien","Martin Van Buren","C","Maarten van Buren, dit Martin Van Buren, né le 5 décembre 1782 à Kinderhook et mort le 24 juillet 1862 dans la même ville, est un homme d'État américain. Membre du Parti démocrate, il est le 8e vice-président des États-Unis, en fonction du 4 mars 1833 au 4 mars 1837, puis le 8e président des États-Unis, en fonction du 4 mars 1837 au 4 mars 1841.",115,"fr:Martin_Van_Buren","c:0/0b/Martin_Van_Buren_by_Mathew_Brady_c1855-58_sepia_original_restored.jpg"],["Q9387",126,"politicien","Max Weber","C","Max Weber, né le 21 avril 1864 à Erfurt, alors dans le royaume de Prusse, et mort le 14 juin 1920 à Munich, est un économiste et sociologue allemand originellement formé en droit.",114,"fr:Max_Weber","c:1/16/Max_Weber_1894.jpg"],["Q44197",127,"politicien","Maximilien de Robespierre","R","Maximilien de Robespierre, ou Maximilien Robespierre, est un avocat et homme politique français né le 6 mai 1758 à Arras et mort guillotiné le 28 juillet 1794 à Paris, place de la Révolution. Il est l'une des principales figures de la Révolution française et demeure l'un des personnages les plus controversés de cette période.",114,"fr:Maximilien_de_Robespierre","c:1/12/Robespierre.jpg"],["Q19526",128,"politicien","Maya Angelou","PC","Maya Angelou, de son vrai nom Marguerite Annie Johnson, née le 4 avril 1928 à Saint-Louis aux États-Unis, et morte le 28 mai 2014 à Winston-Salem, est une romancière, poète, dramaturge essayiste, actrice, scénariste, productrice, documentariste, professeure d'université et militante afro-américaine.",117,"fr:Maya_Angelou","c:8/83/Maya_Angelou_visits_YCP_Feb_2013.jpg"],["Q41568",129,"politicien","Michel de Montaigne","C","Michel Eyquem, seigneur de Montaigne, plus connu sous la simple dénomination de Montaigne, né le 28 février 1533 au château de Saint-Michel-de-Montaigne et mort le 13 septembre 1592 dans la même ville, est un philosophe, humaniste, écrivain érudit et moraliste français de la Renaissance.",115,"fr:Michel_de_Montaigne","c:a/ac/Montaigne-Dumonstier.jpg"],["Q13133",130,"politicien","Michelle Obama","PC","Michelle Obama, née Michelle Robinson le 17 janvier 1964 à Chicago, est une avocate, essayiste et activiste américaine.",null,"fr:Michelle_Obama","c:4/4b/Michelle_Obama_2013_official_portrait.jpg",{"cats":["politique","usa"]}],["Q27645",131,"politicien","Mikhaïl Bakounine","C","Mikhaïl Aleksandrovitch Bakounine, francisé en Michel Bakounine, né le 18 mai 1814 à Priamoukhino près de Torjok et mort le 1er juillet 1876 à Berne, est un révolutionnaire, théoricien de l'anarchisme et philosophe russe qui a particulièrement écrit sur le rôle de l'État. Il pose dans ses écrits les fondements du socialisme libertaire.",115,"fr:Mikhaïl_Bakounine","c:9/9b/Bakunin.png"],["Q30487",132,"politicien","Mikhaïl Gorbatchev","R","Mikhaïl Sergueïevitch Gorbatchev ou Gorbatchiov, né le 2 mars 1931 à Privolnoïe et mort le 30 août 2022 à Moscou, est un homme d'État soviétique puis russe.",117,"fr:Mikhaïl_Gorbatchev","c:1/1b/GorbachevMS.jpg"],["Q12306",133,"politicien","Millard Fillmore","C","Millard Fillmore, né le 7 janvier 1800 à Locke et mort le 8 mars 1874 à Buffalo, est un homme d'État américain. Membre du Parti whig, il est le 12e vice-président des États-Unis, en fonction du 4 mars 1849 au 9 juillet 1850, puis le 13e président des États-Unis, en fonction du 9 juillet 1850 au 4 mars 1853.","Millard Fillmore, né le 7 janvier 1800 à Locke et mort le 8 mars 1874 à Buffalo, est un homme d'État américain.","fr:Millard_Fillmore","c:4/43/Millard_Fillmore_Better_Crop.jpg"],["Q1001",134,"politicien","Mohandas Karamchand Gandhi","E","Mohandas Karamchand Gandhi, né à Porbandar le 2 octobre 1869 et mort assassiné à New Delhi le 30 janvier 1948, est un avocat indien, un nationaliste, anti-colonialiste et une personnalité politique connue pour avoir employé la résistance non violente.",117,"fr:Mohandas_Karamchand_Gandhi","c:7/7a/Mahatma-Gandhi%2C_studio%2C_1931.jpg"],["Q19878",135,"politicien","Mouammar Kadhafi","R","Mouammar Kadhafi, né vers 1942 à Qasr Abou Hadi et mort le 20 octobre 2011 dans les environs de Syrte, est un militaire et homme d'État libyen. Il est le dirigeant de la Libye de 1969 jusqu'à sa chute en 2011.",119,"fr:Mouammar_Kadhafi","c:b/b5/Muammar_al-Gaddafi_at_the_AU_summit_%283x4%29.jpg"],["Q5152",136,"politicien","Mustafa Kemal Atatürk","R","Mustafa Kemal Atatürk, jusqu'en 1934 Mustafa Kemal Pacha, puis Kemal Atatürk, est un militaire et homme d'État turc né à Thessalonique en 1881 et mort à Istanbul le 10 novembre 1938. Il est le fondateur et premier président de la république de Turquie de 1923 à sa mort.",118,"fr:Mustafa_Kemal_Atatürk","c:a/a8/Ataturk1930s.jpg"],["Q1058",138,"politicien","Narendra Modi","R","Narendra Modi, né le 17 septembre 1950 à Vadnagar, est un homme d’État indien, Premier ministre depuis 2014.",null,"fr:Narendra_Modi","c:b/ba/Narendra_Modi_Portrait_2026.jpg"],["Q8023",139,"politicien","Nelson Mandela","R","Nelson Rolihlahla Mandela, dont le nom du clan tribal est « Madiba », né le 18 juillet 1918 à Mvezo et mort le 5 décembre 2013 à Johannesburg, est un homme d'État sud-africain. Il a été l'un des dirigeants historiques de la lutte contre le système politique institutionnel de ségrégation raciale de l'apartheid, avant de devenir président de la république d'Afrique du Sud de 1994 à 1999, à la suite des premières élections nationales non ségrégationnistes de l'histoire du pays.",112,"fr:Nelson_Mandela","c:0/02/Nelson_Mandela_1994.jpg"],["Q329",141,"politicien","Nicolas Sarkozy","E","Nicolas Sarközy de Nagy-Bocsa, dit Nicolas Sarkozy, né le 28 janvier 1955 à Paris 17e, est un homme d'État français. Il est président de la République française du 16 mai 2007 au 15 mai 2012.","Nicolas Sarközy de Nagy-Bocsa, dit Nicolas Sarkozy, né le 28 janvier 1955 à Paris 17e, est un homme d'État français.","fr:Nicolas_Sarkozy","c:4/4a/Nicolas_Sarkozy_20220927.jpg",{"cats":["politique","politique_fr"]}],["Q58132",142,"politicien","Nicolás Maduro","PC","Nicolás Maduro Moros, né le 23 novembre 1962 à Caracas, est un syndicaliste et homme d'État vénézuélien. Il est président de la république bolivarienne du Venezuela du 8 mars 2013 jusque de facto au 3 janvier 2026, à la suite de son enlèvement hors du pays par les États-Unis. La légitimité de sa réélection pour son troisième mandat le 29 juillet 2024 est mise en question par l'administration Trump, par ses opposants dans le pays et par une grande partie de la communauté internationale.","Nicolás Maduro Moros, né le 23 novembre 1962 à Caracas, est un syndicaliste et homme d'État vénézuélien.","fr:Nicolás_Maduro","c:f/f4/Nicol%C3%A1s_Maduro_official_portrait_%28cropped_2%29.png"],["Q35314",143,"politicien","Nikita Khrouchtchev","R","Nikita Sergueïevitch Khrouchtchev, né le 3 avril 1894 à Kalinovka, dans l'Empire russe, et mort le 11 septembre 1971 à Moscou, est un homme d'État soviétique qui dirigea l'URSS durant une partie de la guerre froide. Il est premier secrétaire du Parti communiste de l'Union soviétique de 1953 à 1964 et président du conseil des ministres de 1958 à 1964.",118,"fr:Nikita_Khrouchtchev","c:4/4d/1956_Press_Photo_Communist_Party_Secretary_Nikita_S._Khrushchev_in_Moscow_%28cropped%29.jpg"],["Q8467",145,"politicien","Omar ibn al-Khattâb","PC","Omar ibn al-Khattab, surnommé Al-Farouq « le Discernateur », né vers 584 à La Mecque et mort assassiné le 7 novembre 644 à Médine, est un compagnon du prophète de l'islam Mahomet et le deuxième calife des quatre califes bien guidés. Succédant à Abou Bakr en août 634, il règne pendant dix ans jusqu'à son assassinat.",116,"fr:Omar_ibn_al-Khattâb","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a3/Rashidun_Caliphs_Umar_ibn_Al-Khatt%C4%81b_-_%D8%B9%D9%8F%D9%85%D8%B1_%D8%A8%D9%86_%D8%A7%D9%84%D8%AE%D8%B7%D9%91%D8%A7%D8%A8_%D8%AB%D8%A7%D9%86%D9%8A_%D8%A7%D9%84%D8%AE%D9%84%D9%81%D8%A7%D8%A1_%D8%A7%D9%84%D8%B1%D8%A7%D8%B4%D8%AF%D9%8A%D9%86.svg/330px-Rashidun_Caliphs_Umar_ibn_Al-Khatt%C4%81b_-_%D8%B9%D9%8F%D9%85%D8%B1_%D8%A8%D9%86_%D8%A7%D9%84%D8%AE%D8%B7%D9%91%D8%A7%D8%A8_%D8%AB%D8%A7%D9%86%D9%8A_%D8%A7%D9%84%D8%AE%D9%84%D9%81%D8%A7%D8%A1_%D8%A7%D9%84%D8%B1%D8%A7%D8%B4%D8%AF%D9%8A%D9%86.svg.png",{"cats":["politique","religions"]}],["Q8442",146,"politicien","Otto von Bismarck","PC","Otto von Bismarck /ˈɔto fɔn ˈbɪsmaʁk/, duc de Lauenburg et prince de Bismarck, né le 1er avril 1815 à Schönhausen et mort le 30 juillet 1898 à Friedrichsruh, est un homme d'État prussien puis allemand.",116,"fr:Otto_von_Bismarck","c:1/10/Bundesarchiv_Bild_146-2005-0057%2C_Otto_von_Bismarck.jpg"],["Q34189",147,"politicien","Pablo Neruda","C","Pablo Neruda, nom de plume de Ricardo Eliécer Neftalí Reyes Basoalto, né le 12 juillet 1904 à Parral et mort le 23 septembre 1973 à Santiago, est un poète, écrivain, diplomate, homme politique et intellectuel chilien.",114,"fr:Pablo_Neruda","c:8/86/Pablo_Neruda_1963.jpg"],["Q39464",150,"politicien","Pol Pot","R","Saloth Sâr, né le 19 mai 1925 et mort le 15 avril 1998, plus connu sous le nom de Pol Pot, est un homme d'État cambodgien, chef des Khmers rouges et du Parti communiste du Kampuchéa.",110,"fr:Pol_Pot","c:f/fe/Pol_Pot_in_1978.png"],["Q7192",151,"politicien","Qin Shi Huang","PC","Qin Shi Huang, ou Qin Shi Huangdi, fut d'abord le roi de Qin de 247 à 221 av. J.-C. Il mit fin à la période féodale en conquérant un à un l'ensemble des Royaumes combattants entre 230 et 221 av. J.-C. et devint l'unificateur de l'Empire de Chine, et par conséquent l'empereur fondateur de la dynastie Qin.","Qin Shi Huang, ou Qin Shi Huangdi, fut d'abord le roi de Qin de 247 à 221 av.","fr:Qin_Shi_Huang","c:2/27/Qinshihuang.jpg"],["Q19581",152,"politicien","Rafael Correa","C","Rafael Vicente Correa Delgado, né le 6 avril 1963 à Guayaquil, est un économiste et homme d'État équatorien, président de la République du 15 janvier 2007 au 24 mai 2017.",118,"fr:Rafael_Correa","c:3/36/Rafael_Correa_2024.jpg"],["Q39259",153,"politicien","Recep Tayyip Erdoğan","PC","Recep Tayyip Erdoğan, né le 26 février 1954 à Beyoğlu, est un homme d'État turc. Cofondateur du Parti de la justice et du développement, il est Premier ministre de 2003 à 2014 et président de la République depuis 2014, étant à ces deux fonctions l'homme fort du pays.","Recep Tayyip Erdoğan, né le 26 février 1954 à Beyoğlu, est un homme d'État turc.","fr:Recep_Tayyip_Erdoğan","c:2/2d/Recep_Tayyip_Erdogan_in_Ukraine.jpg"],["Q9588",154,"politicien","Richard Nixon","E","Richard Nixon, né le 9 janvier 1913 à Yorba Linda et mort le 22 avril 1994 à New York, est un homme d'État américain. Membre du Parti républicain, il est le 36e vice-président des États-Unis, en fonction du 20 janvier 1953 au 20 janvier 1961, et le 37e président des États-Unis, en fonction du 20 janvier 1969 jusqu'à sa démission le 9 août 1974.","Richard Nixon, né le 9 janvier 1913 à Yorba Linda et mort le 22 avril 1994 à New York, est un homme d'État américain.","fr:Richard_Nixon","c:2/2c/Richard_Nixon_presidential_portrait_%281%29.jpg",{"cats":["politique","usa"]}],["Q20055561",155,"politicien","Rishi Sunak","PC","Rishi Sunak, né le 12 mai 1980 à Southampton, est un homme d'État britannique. Il est Premier ministre du Royaume-Uni du 25 octobre 2022 au 5 juillet 2024, en sa qualité de chef du Parti conservateur.","Rishi Sunak, né le 12 mai 1980 à Southampton, est un homme d'État britannique.","fr:Rishi_Sunak","c:a/ab/Portrait_of_Prime_Minister_Rishi_Sunak_%28cropped%29.jpg"],["Q10707",156,"politicien","Robert Mugabe","C","Robert Gabriel Karigamombe Mugabe, dit Robert Mugabe, né le 21 février 1924 à Kutama en Rhodésie du Sud et mort le 6 septembre 2019 à Singapour, est un homme d'État zimbabwéen. Il est Premier ministre de 1980 à 1987 et président de la république du Zimbabwe de 1987 à 2017.",116,"fr:Robert_Mugabe","c:5/55/Robert_Mugabe_Official_Portrait.jpg"],["Q15981",157,"politicien","Robert Schuman","C","Robert Schuman, né Jean-Baptiste Nicolas Robert Schuman le 29 juin 1886 à Luxembourg et mort le 4 septembre 1963 à Scy-Chazelles, est un homme d'État français. Sous-secrétaire d'État pendant la Troisième République puis ministre pendant la Quatrième République, notamment aux Affaires étrangères et président du Conseil des ministres à deux reprises, Schuman a exercé par ailleurs les fonctions de président du Parlement européen.",114,"fr:Robert_Schuman","c:a/ae/Robert_Schuman_1958.jpg"],["Q9960",158,"politicien","Ronald Reagan","E","Ronald Wilson Reagan, né le 6 février 1911 à Tampico et mort le 5 juin 2004 à Los Angeles, est un acteur et homme d'État américain. Membre du Parti républicain, il est le 40e président des États-Unis, en fonction du 20 janvier 1981 au 20 janvier 1989.",113,"fr:Ronald_Reagan","c:1/16/Official_Portrait_of_President_Reagan_1981.jpg",{"cats":["politique","usa"]}],["Q7231",159,"politicien","Rosa Luxemburg","PC","Rosa Luxemburg, en polonais Róża Luksemburg, parfois retranscrit, à tort, en français, Rosa Luxembourg, née Rozalia Luksenburg le 5 mars 1871 à Zamość en Pologne et morte assassinée le 15 janvier 1919 à Berlin en Allemagne, est une militante socialiste et communiste, et une théoricienne marxiste.",115,"fr:Rosa_Luxemburg","c:c/ce/Bundesarchiv_Bild_183-14077-006%2C_Rosa_Luxemburg.jpg"],["Q38823",160,"politicien","Rouhollah Khomeini","PC","Rouhollah Moussavi Khomeini, parfois transcrit Khomeiny ou Khomeyni, né le 17 mai 1900 à Khomein et mort le 3 juin 1989 à Téhéran, est un ayatollah, révolutionnaire et homme d'État iranien.",119,"fr:Rouhollah_Khomeini","c:b/b3/Portrait_of_Ruhollah_Khomeini_By_Ali_Kaveh.jpg"],["Q35686",161,"politicien","Rutherford B. Hayes","C","Rutherford Birchard Hayes, généralement appelé Rutherford B. Hayes, né le 4 octobre 1822 à Delaware et mort le 17 janvier 1893 à Fremont, est un homme d'État américain. Membre du Parti républicain, il est le 19e président des États-Unis, en fonction du 4 mars 1877 au 4 mars 1881. Après une élection contestée en 1876, Hayes supervise la fin de la Reconstruction et restaure la confiance dans le gouvernement fédéral.","Rutherford Birchard Hayes, généralement appelé Rutherford B.","fr:Rutherford_B._Hayes","c:5/50/President_Rutherford_Hayes_1870_-_1880_Restored.jpg"],["Q1316",162,"politicien","Saddam Hussein","R","Saddam Hussein Al-Majid, communément appelé Saddam Hussein, est un homme d'État irakien, présumément né le 28 avril 1937 à Al-Awja, près de Tikrit, et exécuté par pendaison le 30 décembre 2006 à Bagdad. Cinquième président de la république d'Irak, il occupe ce poste du 16 juillet 1979 au 9 avril 2003. Membre dirigeant du parti Baas arabe socialiste, il conserve sa position d'influence lors de la scission du parti et dirige la branche régionale irakienne de l'organisation.",115,"fr:Saddam_Hussein","c:9/9a/Saddam_Hussein_in_1998.png"],["Q298180",165,"politicien","Simone Veil","R","Simone Veil, née Jacob le 13 juillet 1927 à Nice et morte le 30 juin 2017 à Paris 7e, est une magistrate et femme d'État française.",113,"fr:Simone_Veil","c:f/fc/Official_portrait_of_Simone_Veil_%28cropped%29.jpg",{"cats":["politique","politique_fr"]}],["Q8605",166,"politicien","Simón Bolívar","PC","Simón Bolívar, de son nom complet Simón José Antonio de la Santísima Trinidad Bolívar y Palacios, surnommé El Libertador, né le 24 juillet 1783 à Caracas dans la vice-royauté de Nouvelle-Grenade, et mort le 17 décembre 1830 à Santa Marta en Grande Colombie, est un général et homme d'État vénézuélien.",109,"fr:Simón_Bolívar","c:5/5f/Portrait_of_Sim%C3%B3n_Bol%C3%ADvar_by_Arturo_Michelena.jpg"],["Q8474",167,"politicien","Soliman le Magnifique","PC","Soliman Ier (turc ottoman: سلطان سليمان اول; turc: I. Süleyman) est probablement né le 6 novembre 1494 à Trébizonde dans l'actuelle Turquie et mort le 6 septembre 1566 à Szigetvár dans l'actuelle Hongrie","Soliman Ier (turc ottoman: سلطان سليمان اول; turc: I.","fr:Soliman_le_Magnifique","c:f/f7/Suleyman_%28enthroned%2C_receiving_Barbarossa_in_1533%29._S%C3%BCleymanname_%281558%29.jpg"],["Q8573",168,"politicien","Sun Yat-sen","C","Sun Yat-sen, plus connu en Chine sous son surnom Sun Zhongshan, également appelé Sun Wen, né le 12 novembre 1866 et mort le 12 mars 1925, est un révolutionnaire et homme d'État chinois.",115,"fr:Sun_Yat-sen","c:8/80/Sun_Yat-sen_2.jpg"],["Q2054",169,"politicien","Sénèque","C","Sénèque, parfois nommé Sénèque le Jeune, Sénèque le Philosophe ou Sénèque le Tragique, né vers l'an 4 av. J.-C. à Corduba et mort le 12 avril 65 à Rome, est un homme d'État romain, un philosophe et un dramaturge.","Sénèque, parfois nommé Sénèque le Jeune, Sénèque le Philosophe ou Sénèque le Tragique, né vers l'an 4 av.","fr:Sénèque","c:4/44/Duble_herma_of_Socrates_and_Seneca_Antikensammlung_Berlin_07.jpg"],["Q2161",170,"politicien","Tacite","C","Tacite, en latin Publius Cornelius Tacitus Ca, né en 58 et mort vers 120 ap. J.-C, mène comme sénateur romain une carrière dans la haute administration impériale. Il est renommé comme historien, grâce à ses ouvrages les Annales et les Histoires, chronique de la période des quatre empereurs julio-claudiens après Auguste.","Tacite, en latin Publius Cornelius Tacitus Ca, né en 58 et mort vers 120 ap.","fr:Tacite","c:c/cc/Tacitus%2C_Cornelius_%2850_-_116%29.jpg"],["Q16574",171,"politicien","Tchang Kaï-chek","R","Tchang Kaï-chek est un militaire et homme d'État chinois né le 31 octobre 1887 et mort le 5 avril 1975 à Taipei. Il est le dirigeant de la république de Chine de 1928 à sa mort. Son gouvernement est d'abord basé en Chine continentale jusqu'à sa défaite lors de la guerre civile chinoise, face au Parti communiste en 1949. Il continue par la suite de diriger la république de Chine sur l'île de Taïwan.","Tchang Kaï-chek est un militaire et homme d'État chinois né le 31 octobre 1887 et mort le 5 avril 1975 à Taipei.","fr:Tchang_Kaï-chek","c:2/27/%E8%94%A3%E4%B8%AD%E6%AD%A3%E7%B8%BD%E7%B5%B1%E7%8E%89%E7%85%A7.png"],["Q17293",172,"politicien","Tenzin Gyatso","E","Tenzin Gyatso, né Lhamo Dhondup le 6 juillet 1935 à Taktser (Hongya en chinois), dans la province du Qinghai, est le 14e dalaï-lama.",116,"fr:Tenzin_Gyatso","c:f/fb/The_Dalai_Lama_in_2012.jpg",{"cats":["politique","religions"]}],["Q2072384",173,"politicien","Theo Francken","C","Theo J.E. Francken, né le 7 février 1978 à Lubbeek en Belgique, est un homme politique belge membre du parti nationaliste flamand N-VA, secrétaire d'État à l'Asile et aux Migrations et responsable de la Simplification administrative dans le gouvernement Michel I du 11 octobre 2014 au 9 décembre 2018.","Theo J.E.","fr:Theo_Francken","c:d/d4/Theo_Francken_N-VA_%28cropped%29.jpg"],["Q33866",174,"politicien","Theodore Roosevelt","E","Theodore Roosevelt, né le 27 octobre 1858 à New York et mort le 6 janvier 1919 à Oyster Bay, est un homme d'État américain. Membre du Parti républicain, il est le 25e vice-président des États-Unis, en fonction du 4 mars au 14 septembre 1901, puis le 26e président des États-Unis, en fonction du 14 septembre 1901 au 4 mars 1909. Il est lauréat du prix Nobel de la paix en 1906 grâce à son rôle de médiateur dans la guerre russo-japonaise.",112,"fr:Theodore_Roosevelt","c:5/5b/Theodore_Roosevelt_by_the_Pach_Bros.jpg",{"cats":["politique","usa"]}],["Q264766",175,"politicien","Theresa May","C","Theresa May /təˈɹiːzə ˈmeɪ/, baronne May de Maidenhead, née Theresa Brasier le 1er octobre 1956 à Eastbourne, est une femme d'État britannique. Elle est dirigeante du Parti conservateur et Première ministre du Royaume-Uni de 2016 à 2019.",117,"fr:Theresa_May","c:d/d1/Official_portrait_of_Baroness_May_of_Maidenhead_crop_2.jpg"],["Q11812",176,"politicien","Thomas Jefferson","R","Thomas Jefferson, né le 13 avril 1743 à Shadwell et mort le 4 juillet 1826 à Monticello, est un philosophe politique, diplomate, architecte et homme d'État américain. Membre du Parti républicain-démocrate, il est le 2e vice-président des États-Unis, en fonction du 4 mars 1797 au 4 mars 1801, puis le 3e président des États-Unis, en fonction du 4 mars 1801 au 4 mars 1809.",117,"fr:Thomas_Jefferson","c:0/07/Official_Presidential_portrait_of_Thomas_Jefferson_%28by_Rembrandt_Peale%2C_1800%29.jpg",{"cats":["politique","usa"]}],["Q42544",177,"politicien","Thomas More","PC","Thomas More, latinisé en Thomas Morus, est un saint catholique, juriste, historien, philosophe, humaniste, théologien et homme politique anglais. Grand ami d'Érasme, érudit, philanthrope, il participe pleinement au renouveau de la pensée qui caractérise cette époque, ainsi qu'à l'humanisme, dont il est l'un des représentants anglais.",117,"fr:Thomas_More","c:d/d2/Hans_Holbein%2C_the_Younger_-_Sir_Thomas_More_-_Google_Art_Project.jpg"],["Q126462",178,"politicien","Thomas Paine","C","Thomas Paine, né le 9 février 1737 à Thetford, près de Londres et mort le 8 juin 1809 à New York, est un philosophe, pamphlétaire, révolutionnaire britannique, américain et français.",116,"fr:Thomas_Paine","c:b/bc/Laurent_Dabos_%E2%80%93_Thomas_Paine_%E2%80%93_Google_Art_Project.jpg"],["Q9545",179,"politicien","Tony Blair","PC","Tony Blair (/ˈtəʊni blɛə/), de son nom complet Anthony Charles Lynton Blair, est un homme d'État britannique, membre du Parti travailliste, né le 6 mai 1953 à Édimbourg. Il est Premier ministre du Royaume-Uni du 2 mai 1997 au 27 juin 2007.",119,"fr:Tony_Blair","c:b/bd/Presidente_Bernardo_Ar%C3%A9valo_se_re%C3%BAne_con_Tony_Blair%2C_ex_primer_ministro_del_Reino_Unido_-_54169169198_%28cropped%29.jpg"],["Q34836",180,"politicien","Ulysses S. Grant","PC","Ulysses S. Grant, né le 27 avril 1822 à Point Pleasant et mort le 23 juillet 1885 à Wilton, est un militaire et homme d'État américain. Membre du Parti républicain, il est le 18e président des États-Unis, en fonction du 4 mars 1869 au 4 mars 1877. Grant est célèbre pour avoir commandé les armées unionistes durant la guerre de Sécession.","Ulysses S.","fr:Ulysses_S._Grant","c:5/5c/Ulysses_S._Grant_1870-1880.jpg"],["Q60772",181,"politicien","Ursula von der Leyen","R","Ursula von der Leyen, née Albrecht le 8 octobre 1958 à Ixelles, est une femme d'État allemande. Elle est présidente de la Commission européenne depuis le 1er décembre 2019.","Ursula von der Leyen, née Albrecht le 8 octobre 1958 à Ixelles, est une femme d'État allemande.","fr:Ursula_von_der_Leyen","c:2/20/Brigitte_Macron%2C_Ursula_von_der_Leyen_and_Emmanuel_Macron_in_Nice%2C_France_-_June_2025_%281%29.jpg"],["Q2124",182,"politicien","Valéry Giscard d'Estaing","R","Valéry Giscard d'Estaing, communément appelé « Giscard » et également connu sous ses initiales VGE, né le 2 février 1926 à Coblence et mort le 2 décembre 2020 à Authon, est un homme d'État français. Il est président de la République française du 27 mai 1974 au 21 mai 1981.",115,"fr:Valéry_Giscard_d'Estaing","c:5/5e/Val%C3%A9ry_Giscard_d%27Estaing_%281975%29.jpg",{"cats":["politique","politique_fr"]}],["Q9045",184,"politicien","Vishnugupta Chânakya","C","Vishnugupta Chânakya est un brâhmane et l'un des premiers penseurs politiques indiens connus.",null,"fr:Vishnugupta_Chânakya","c:c/cd/Chanakya_artistic_depiction.jpg"],["Q1394",185,"politicien","Vladimir Ilitch Lénine","E","Vladimir Ilitch Oulianov, dit Lénine, est un révolutionnaire bolchévique, idéologue, théoricien politique communiste et homme d'État russe puis soviétique, né le 10 avril 1870 à Simbirsk et mort le 21 janvier 1924 à Vichnie Gorki.",119,"fr:Vladimir_Ilitch_Lénine","c:c/c0/Lenin_in_1920_%28cropped%29.jpg"],["Q7747",186,"politicien","Vladimir Poutine","L","Vladimir Poutine, né le 7 octobre 1952 à Leningrad, est un homme d'État russe. Depuis 1999, il est la figure centrale de l'exécutif de la nation russe, alternativement comme président du gouvernement et président de la fédération de Russie.","Vladimir Poutine, né le 7 octobre 1952 à Leningrad, est un homme d'État russe.","fr:Vladimir_Poutine","c:5/57/%D0%92%D0%BB%D0%B0%D0%B4%D0%B8%D0%BC%D0%B8%D1%80_%D0%9F%D1%83%D1%82%D0%B8%D0%BD_%2808-03-2024%29_%28cropped%29_%28higher_res%29.jpg"],["Q3874799",187,"politicien","Volodymyr Zelensky","E","Volodymyr Olexandrovytch Zelensky, né le 25 janvier 1978 à Kryvyï Rih en RSS d’Ukraine, est un ancien humoriste, acteur, scénariste, réalisateur et producteur de télévision, devenu homme d'État ukrainien. Il est président de l'Ukraine depuis le 20 mai 2019.",112,"fr:Volodymyr_Zelensky","c:4/41/New_Year%27s_Eve_from_President_of_Ukraine_Volodymyr_Zelensky_%2831-12-2025%29_%28cropped%29.jpg"],["Q36233",188,"politicien","Václav Havel","C","Václav Havel, né le 5 octobre 1936 à Prague et mort le 18 décembre 2011 à Hrádeček, est un dramaturge, essayiste et homme d'État tchécoslovaque puis tchèque.",115,"fr:Václav_Havel","c:a/a4/Vaclav_Havel.jpg"],["Q35286",189,"politicien","Warren G. Harding","PC","Warren Gamaliel Harding, généralement appelé Warren G. Harding, né le 2 novembre 1865 à Blooming Grove et mort le 2 août 1923 à San Francisco, est un homme d'État américain. Membre du Parti républicain, il est le 29e président des États-Unis, en fonction du 4 mars 1921 jusqu'à sa mort.","Warren Gamaliel Harding, généralement appelé Warren G.","fr:Warren_G._Harding","c:c/c4/Warren_G_Harding-Harris_%26_Ewing.jpg"],["Q11869",190,"politicien","William Henry Harrison","C","William Henry Harrison, né le 9 février 1773 à la plantation de Berkeley et mort le 4 avril 1841 à Washington, D.C., est un militaire et homme d'État américain. Membre du Parti whig, il est le 9e président des États-Unis, en fonction du 4 mars 1841 jusqu'à sa mort, un mois plus tard, devenant ainsi le premier président à mourir en exercice et celui au mandat le plus court de l'histoire américaine.",116,"fr:William_Henry_Harrison","c:2/2c/William_Henry_Harrison_crop.jpg"],["Q35648",191,"politicien","William Howard Taft","PC","William Howard Taft, né le 15 septembre 1857 à Cincinnati et mort le 8 mars 1930 à Washington, D.C., est un homme d'État et juriste américain. Membre du Parti républicain, il est le 27e président des États-Unis, en fonction du 4 mars 1909 au 4 mars 1913, et le 10e juge en chef des États-Unis, en fonction du 11 juillet 1921 au 3 février 1930.",113,"fr:William_Howard_Taft","c:9/9b/William_Howard_Taft_1909.jpg"],["Q35041",192,"politicien","William McKinley","PC","William McKinley, né le 29 janvier 1843 à Niles et mort assassiné le 14 septembre 1901 à Buffalo, est un homme d'État américain. Membre du Parti républicain, il est le 25e président des États-Unis, en fonction du 4 mars 1897 jusqu'à sa mort.",117,"fr:William_McKinley","c:6/6d/Mckinley.jpg"],["Q8016",193,"politicien","Winston Churchill","E","Winston Churchill est un homme d'État et écrivain britannique, né le 30 novembre 1874 à Woodstock et mort le 24 janvier 1965 à Londres. Membre du Parti conservateur malgré un intermède au Parti libéral, il est Premier ministre du Royaume-Uni de mai 1940 à juillet 1945 puis d’octobre 1951 à avril 1955; il joue un rôle décisif dans la victoire des Alliés lors de la Seconde Guerre mondiale.",119,"fr:Winston_Churchill","c:0/02/Sir_Winston_Churchill_-_19086236948_%28restored%29.jpg"],["Q34296",194,"politicien","Woodrow Wilson","PC","Woodrow Wilson, né le 28 décembre 1856 à Staunton et mort le 3 février 1924 à Washington, D.C., est un homme d'État américain. Membre du Parti démocrate, il est le 28e président des États-Unis, en fonction du 4 mars 1913 au 4 mars 1921.",115,"fr:Woodrow_Wilson","c:5/53/Thomas_Woodrow_Wilson%2C_Harris_%26_Ewing_bw_photo_portrait%2C_1919.jpg"],["Q15031",195,"politicien","Xi Jinping","L","Xi Jinping, né le 15 juin 1953 à Pékin, est un homme d'État chinois. Il est le président de la république populaire de Chine depuis le 14 mars 2013.","Xi Jinping, né le 15 juin 1953 à Pékin, est un homme d'État chinois.","fr:Xi_Jinping","c:3/37/Xi_Jinping_in_Beijing_on_May_13%2C_2025_%28cropped%29.jpg"],["Q34211",196,"politicien","Yasser Arafat","PC","Yasser Arafat, né le 24 août 1929 au Caire et mort le 11 novembre 2004 à Clamart, de son vrai nom Mohamed Abdel Raouf Arafat al-Qoudwa al-Husseini et connu aussi sous son surnom d'Abou Ammar, est un activiste et homme d'État palestinien.",117,"fr:Yasser_Arafat","c:b/b1/Leader_of_the_PLO%2C_Yasser_Arafat%2C_1996_Dan_Hadani_Archive.jpg"],["Q11896",197,"politicien","Zachary Taylor","C","Zachary Taylor, né le 24 novembre 1784 à Barboursville et mort le 9 juillet 1850 à Washington, D.C., est un militaire et homme d'État américain. Membre du Parti whig, il est le 12e président des États-Unis, en fonction du 4 mars 1849 jusqu'à sa mort.",117,"fr:Zachary_Taylor","c:5/51/Zachary_Taylor_restored_and_cropped.jpg"],["Q57464",198,"monarque","Abdallah II","C","Abdallah II, né le 30 janvier 1962 à Amman, est roi de Jordanie depuis le 7 février 1999, date à laquelle il a succédé à son père, le roi Hussein.",118,"fr:Abdallah_II","c:a/a0/Abdullah_II_portrait_crop_2_at_10_Downing_Street_June_2025.jpg"],["Q151509",199,"monarque","Abdelaziz ibn Saoud","PC","Abdelaziz ben Abderrahmane Al Saoud, dit Ibn Séoud ou Ibn Saoud, né le 15 janvier 1876 ou le 24 novembre 1880 à Riyad et mort le 9 novembre 1953 à Taëf, est le fondateur du troisième État saoudien, l'actuelle Arabie saoudite. Du 8 janvier 1926 à sa mort, il fut le second roi du Hedjaz et du Nejd, et le premier roi de l'Arabie saoudite moderne après l'unification du pays. Il est le père de nombreux enfants, dont six lui succèdent sur le trône saoudien en tant que rois.",117,"fr:Abdelaziz_ibn_Saoud","c:a/a3/Ibn_Saud.png"],["Q8597",200,"monarque","Akbar","C","Jalâluddin Muhammad Akbar, né le 15 octobre 1542 à Amarkot et mort le 27 octobre 1605 à Āgrā, est un empereur moghol. Son règne, qui correspond à l'apogée de l'Empire moghol, est marqué par d'importantes réformes administratives et une tolérance religieuse qui renforcèrent l'unité de son empire. Ses contributions à l'art et à l'architecture firent rayonner la culture moghole dans toute l'Asie du Sud.","Jalâluddin Muhammad Akbar, né le 15 octobre 1542 à Amarkot et mort le 27 octobre 1605 à Āgrā, est un empereur moghol.","fr:Akbar","c:b/b4/Akbar_at_his_court.jpg"],["Q15193",204,"monarque","Alexandre Ier","C","Alexandre Ier ou Alexandre Pavlovitch Romanov, né le 12 décembre 1777 à Saint-Pétersbourg et mort le 19 novembre 1825 à Taganrog, fils de Paul Ier et de Sophie-Dorothée de Wurtemberg, est empereur de Russie du 23 mars 1801 à sa mort ainsi que grand-duc de Finlande et roi de Pologne.",119,"fr:Alexandre_Ier_(empereur_de_Russie)","c:1/1b/George_Dawe_%281781-1829%29_-_Alexander_I%2C_Emperor_of_Russia_%281777-1825%29_-_RCIN_400098_-_Royal_Collection.jpg"],["Q83171",205,"monarque","Alexandre II","C","Alexandre II, empereur de Russie, dit « le Libérateur », est également grand-duc de Finlande et roi de Pologne jusqu'en 1867, date à laquelle la Pologne est formellement annexée par l'Empire russe.",119,"fr:Alexandre_II_(empereur_de_Russie)","c:d/d6/Alexander_II_of_Russia_photo.jpg"],["Q120180",206,"monarque","Alexandre III","C","Alexandre III de Russie, né le 26 février 1845 et mort le 20 octobre 1894, est empereur de Russie, du 2 mars 1881 jusqu'à sa mort. Il est le dernier empereur de Russie mort sur le trône.",113,"fr:Alexandre_III_(empereur_de_Russie)","c:5/51/Tsar_Alexander_III_c._1885.jpg"],["Q83476",207,"monarque","Alfred le Grand","PC","Alfred, né en 848 ou 849 et mort le 26 octobre 899, est roi du Wessex de 871 à sa mort. Il prend le titre de « roi des Anglo-Saxons » à partir de 886, sans jamais contrôler la totalité du territoire anglais. Cinquième fils du roi Æthelwulf, il succède à son frère Æthelred sur le trône du Wessex en 871.","Alfred, né en 848 ou 849 et mort le 26 octobre 899, est roi du Wessex de 871 à sa mort.","fr:Alfred_le_Grand","c:2/22/Statue_d%27Alfred_le_Grand_%C3%A0_Winchester.jpg"],["Q485547",208,"monarque","Aurangzeb","C","Abu Muzaffar Muhiuddin Muhammad Aurangzeb Âlamgir, connu usuellement sous le nom d'Aurangzeb, ou aussi sous le nom d'Âlamgir Ier qu'il s'était choisi pour régner, est le souverain de l'Empire moghol de 1658 à 1707, le dernier des Grands Moghols. C'est une figure très controversée de l'histoire de l'Inde. Sous son règne, l'Empire moghol aura atteint son apogée territorial, devenant la première économie du monde en détenant un quart du PIB mondial.",114,"fr:Aurangzeb","c:2/27/Aurangzeb.png"],["Q797848",209,"monarque","Babur","C","Babur, parfois orthographié Baber, un surnom signifiant la « Panthère », né Zhahîr ud-din Muhammad, le 14 février 1483 à Andijan et mort le 26 décembre 1530 à Agra, est un prince timouride fondateur de l'Empire moghol. Il est descendant de Tamerlan par Miran Shah et de Gengis Khan par sa mère. Son père, Omar Sheikh Mirza, est un turco-mongol, roi de Ferghana, une partie du Turkestan.",118,"fr:Babur","c:7/7a/Humayun_and_Babur_%28Late_Shah_Jahan_Album%29_Babur_detail.jpg"],["Q29574",211,"monarque","Beatrix","C","Beatrix, née le 31 janvier 1938 au palais de Soestdijk, est reine des Pays-Bas du 30 avril 1980 au 30 avril 2013.",null,"fr:Beatrix_(reine_des_Pays-Bas)","c:a/a7/Prinses_Beatrix.jpg"],["Q27695",212,"monarque","Chaka","C","Chaka kaSenzangakhona, aussi appelé Chaka Zoulou ou Shaka Zulu, né en 1787 et mort en 1828, est un roi zoulou. Il est le fondateur du royaume zoulou.","Chaka kaSenzangakhona, aussi appelé Chaka Zoulou ou Shaka Zulu, né en 1787 et mort en 1828, est un roi zoulou.","fr:Chaka_(roi_zoulou)","c:7/73/KingShaka.jpg"],["Q81506",214,"monarque","Charles Ier","R","Charles Ier, né le 19 novembre 1600 à Dunfermline et mort exécuté le 30 janvier 1649 à Londres, est roi d'Angleterre, d'Écosse et d'Irlande de 1625 à son exécution en 1649.",117,"fr:Charles_Ier_(roi_d'Angleterre)","c:4/46/Charles_I_%281630s%29.jpg"],["Q122553",215,"monarque","Charles II","PC","Charles II, né le 29 mai 1630 au Palais Saint James à Londres et mort le 6 février 1685 au palais de Whitehall à Londres, est roi d'Angleterre, d'Écosse et d'Irlande de 1660 à sa mort.",112,"fr:Charles_II_(roi_d'Angleterre)","c:5/59/Charles2p.jpg"],["Q45068",217,"monarque","Charles XVI Gustave","C","Charles XVI Gustave ou Carl XVI Gustaf, né le 30 avril 1946 à Solna, est l’actuel roi de Suède. Fils du prince héritier Gustave-Adolphe, il succède sur le trône à son grand-père Gustave VI Adolphe, le 15 septembre 1973.","Charles XVI Gustave ou Carl XVI Gustaf, né le 30 avril 1946 à Solna, est l’actuel roi de Suède.","fr:Charles_XVI_Gustave","c:4/42/06.11.2025_%E2%80%93_Recep%C3%A7%C3%A3o_Oficial_dos_Chefes_de_Delega%C3%A7%C3%A3o_da_C%C3%BApula_do_Clima_%2854906269035%29_%28Carlos_XVI_Gustavo%29.jpg"],["Q47842",218,"monarque","Cixi","C","Cixi, ou Tseu-Hi, ou Ts'eu-hi, née le 29 novembre 1835 à Pékin et morte le 15 novembre 1908 à la Cité interdite, est une impératrice douairière de Chine de la dynastie Qing qui exerce la réalité du pouvoir en Chine pendant 47 ans, de 1861 à sa mort.",116,"fr:Cixi","c:7/7a/The_Ci-Xi_Imperial_Dowager_Empress_%289.2%29.PNG"],["Q82339",219,"monarque","Clovis Ier","C","Clovis Ier, en latin Chlodovechus, né vers 466 et mort à Paris le 27 novembre 511, est roi des Francs saliens, puis roi de tous les Francs de 481 à 511.",119,"fr:Clovis_Ier","c:4/41/Saint_Remy_baptise_Clovis_d%C3%A9tail.jpg"],["Q635",220,"monarque","Cléopâtre VII","L","Cléopâtre VII Philopator ou simplement Cléopâtre, née vers 69 av. J.-C. à Alexandrie et morte dans la même ville le 12 août 30 av. J.-C., est une reine d'Égypte antique de la dynastie lagide.","Cléopâtre VII Philopator ou simplement Cléopâtre, née vers 69 av.","fr:Cléopâtre_VII","c:3/3a/Cleopatra_VII%2C_dalla_via_appia_tra_ariccia_e_genzano%2C_40-30_ac_ca._02.JPG"],["Q8423",221,"monarque","Cyrus le Grand","PC","Cyrus II, dit Cyrus le Grand, est un roi perse, régnant d'environ 559 à 530 av. J.-C. Il est le fondateur de l'Empire perse achéménide.","Cyrus II, dit Cyrus le Grand, est un roi perse, régnant d'environ 559 à 530 av.","fr:Cyrus_le_Grand","c:0/02/Cyrus_II_%28The_Great%29.jpg"],["Q44387",222,"monarque","Darius Ier","C","Darius Ier dit le Grand (en vieux perse: 𐎭𐎠𐎼𐎹𐎺𐎢𐏁 / Dārayavauš; en persan: داريوش / Dāriyūš; en grec: Δαρεῖος / Dareīos; en babylonien: Dariamuš; en élamite: Dariyamauiš ou Da-ri-a-ma-u-iš; en araméen: Dryhwš, en hébreu: דָּרְיָוֶשׁ / Darəyaveš; en latin: Darius; « Celui qui soutient le Bien »), né vers 550, mort en 486 av. J.-C., est le troisième grand roi perse de la dynastie des Achéménides. Selon Hérodote, en grec son nom signifie « celui qui réprime ».","Darius Ier dit le Grand (en vieux perse: 𐎭𐎠𐎼𐎹𐎺𐎢𐏁 / Dārayavauš; en persan: داريوش / Dāriyūš; en grec: Δαρεῖος / Dareīos;…","fr:Darius_Ier","c:0/01/Darius_I_%28The_Great%29.jpg"],["Q43107",223,"monarque","Dioclétien","C","Dioclétien, de son nom complet Caius Aurelius Valerius Diocletianus Augustus, né vers le 22 décembre 244 à Salona, et mort le 3 décembre 311/312 à Split, est un empereur romain qui règne du 20 novembre 284 au 1er mai 305.",117,"fr:Dioclétien","c:2/2c/Testa_di_diocleziano%2C_284-305_dc.%2C_da_nicomedia_%28izmit%29.jpg"],["Q129857",224,"monarque","François Ier","PC","François Ier, né sous le nom de François d’Angoulême le 12 septembre 1494 à Cognac et mort le 31 mars 1547 à Rambouillet, est roi de France de 1515 jusqu’à sa mort. Fils de Charles d'Orléans et de Louise de Savoie, il appartient à la branche de Valois-Angoulême de la dynastie capétienne.",108,"fr:François_Ier_(roi_de_France)","c:8/87/Fran%C3%A7ois_Ier_Louvre.jpg"],["Q51056",225,"monarque","François-Joseph Ier","PC","François-Joseph Ier, né le 18 août 1830 à Vienne et mort le 21 novembre 1916 dans la même ville, est monarque d'Autriche-Hongrie, plus précisément empereur d’Autriche et roi apostolique de Hongrie. Membre de la maison de Habsbourg-Lorraine, il règne sur l'Autriche et la Hongrie du 2 décembre 1848 jusqu'à sa mort. Du 1er mai 1850 au 24 août 1866, il occupe également la fonction de président de la Confédération germanique.",109,"fr:François-Joseph_Ier","c:3/3d/Franz_Joseph_I_of_Austria.1910_%28cropped%29.jpg"],["Q33550",226,"monarque","Frédéric II","PC","Frédéric II de Prusse, dit Frédéric le Grand, né le 24 janvier 1712 à Berlin et mort le 17 août 1786 à Potsdam, de la maison de Hohenzollern, est roi de Prusse de 1740 à 1786, le premier à porter officiellement ce titre. Il est simultanément le 14e prince-électeur de Brandebourg.",117,"fr:Frédéric_II_(roi_de_Prusse)","c:9/90/Friedrich_Zweite_Alt.jpg"],["Q720",227,"monarque","Gengis Khan","E","Temüjin Borjigin, dit Gengis Khan, né vers 1155 ou 1162 dans le Khamag Mongol, l'actuelle province de Khentii en Mongolie, et mort en août 1227 dans l'actuel xian de Qingshui, est le fondateur de l'Empire mongol.",112,"fr:Gengis_Khan","c:3/35/YuanEmperorAlbumGenghisPortrait.jpg"],["Q127318",228,"monarque","George III","R","George III, né George William Frederick le 4 juin 1738 à Londres et mort le 29 janvier 1820 au château de Windsor, est roi de Grande-Bretagne et roi d'Irlande à partir du 25 octobre 1760 puis roi du Royaume-Uni de Grande-Bretagne et d'Irlande après l'union des deux pays le 1er janvier 1801. Il est également prince-électeur de Hanovre au sein du Saint-Empire romain germanique puis roi de Hanovre à partir du 12 octobre 1814. Il est brièvement roi de Corse du 17 juin 1794 au 19 octobre 1796.",118,"fr:George_III","c:8/8f/Allan_Ramsay_-_King_George_III_in_coronation_robes_-_Google_Art_Project.jpg"],["Q269412",229,"monarque","George V","E","George V, né George Frederick Ernest Albert le 3 juin 1865 à Londres et mort le 20 janvier 1936 à Sandringham, est roi du Royaume-Uni et des dominions, ainsi qu'empereur des Indes du 6 mai 1910 jusqu'à sa mort.",118,"fr:George_V","c:c/c9/King_George_1923_LCCN2014715558_%28cropped%29.jpg"],["Q280856",230,"monarque","George VI","E","George VI, né Albert Frederick Arthur George le 14 décembre 1895 à Sandringham et mort le 6 février 1952 en ce même lieu, est roi du Royaume-Uni et des autres dominions du Commonwealth britannique du 11 décembre 1936 jusqu'à sa mort. Il est également le dernier empereur des Indes, le dernier roi d'Irlande et le premier chef du Commonwealth.",115,"fr:George_VI","c:7/73/Georg_VI_England.jpg"],["Q2677",231,"monarque","Guillaume II","PC","Guillaume II, né le 27 janvier 1859 à Berlin et mort le 4 juin 1941 à Doorn, aux Pays-Bas, est le troisième et dernier empereur allemand ainsi que le neuvième roi de Prusse, du 15 juin 1888 à son abdication le 9 novembre 1918. Membre de la maison de Hohenzollern, il est le petit-fils de Guillaume Ier et le fils de Frédéric III, qui ne régna que 99 jours et à qui il succéda.",118,"fr:Guillaume_II_(empereur_allemand)","c:6/6e/Kaiser_Wilhelm_II_of_Germany_-_1902.jpg"],["Q130822",232,"monarque","Guillaume IV","PC","Guillaume IV, né William Henry le 21 août 1765 au palais de Buckingham et mort le 20 juin 1837 au château de Windsor, comte de Munster et duc de Clarence et St-Andrews en 1789, est roi du Royaume-Uni de Grande-Bretagne et d'Irlande et de Hanovre du 26 juin 1830 jusqu'à sa mort.",117,"fr:Guillaume_IV_(roi_du_Royaume-Uni)","c:a/a8/William_IV_in_1833_by_Shee.jpg"],["Q37594",233,"monarque","Guillaume le Conquérant","R","Guillaume le Conquérant, appelé également Guillaume le Bâtard ou Guillaume de Normandie, né en 1027 ou 1028 à Falaise et mort le 9 septembre 1087 à Rouen, fut duc de Normandie, sous le nom de Guillaume II, de 1035 à sa mort, et roi d'Angleterre, sous le nom de Guillaume Ier, de 1066 à sa mort.",117,"fr:Guillaume_le_Conquérant","c:a/a8/Bayeux_Tapestry_William.jpg"],["Q36359",234,"monarque","Hammurabi","C","Hammurabi, aussi appelé Hammourabi ou Hammurapi, est le sixième roi amorrite de Babylone, membre de la première dynastie babylonienne, régnant de c. 1792 av. J.-C. à c. 1750 av. J.-C.. Il succède à son père, Sin-muballit.",111,"fr:Hammurabi","c:9/98/F0182_Louvre_Code_Hammourabi_Bas-relief_Sb8_rwk.jpg"],["Q57287",235,"monarque","Harald V","C","Harald V, né le 21 février 1937 à Asker et mort le 28 août 2026 à Oslo, est roi de Norvège du 17 janvier 1991 à sa mort le 28 août 2026. Il est issu de la maison d'Oldenbourg.",119,"fr:Harald_V","c:4/4a/King_Harald_V_may_2026_%28cropped%29.jpg"],["Q129234",236,"monarque","Hatchepsout","C","Hatchepsout est une reine de l'Égypte antique, qui est devenue pharaonne, cinquième souveraine de la XVIIIe dynastie.",null,"fr:Hatchepsout","c:4/46/WLANL_-_koopmanrob_-_Maat-ka-Re_Hatsjepsoet_%28RMO%29.jpg"],["Q41178",237,"monarque","Haïlé Sélassié Ier","PC","Tafari Makonnen, né le 23 juillet 1892 à Ejersa Goro, dans l'Empire éthiopien, et mort assassiné le 27 août 1975 à Addis-Abeba, a été le dernier empereur d'Éthiopie de 1930 à 1936 et de 1941 à 1974. Il règne sous le nom de Haïlé Sélassié Ier.",114,"fr:Haïlé_Sélassié_Ier","c:8/81/Haile_Selassie_in_full_dress.jpg"],["Q936976",238,"monarque","Henri IV","PC","Henri IV, dit « le Grand » ou « le Vert Galant », ou encore « Le Bon Roi Henri », né sous le nom d'Henri de Bourbon le 13 décembre 1553 à Pau et mort assassiné le 14 mai 1610 à Paris, est roi de Navarre à partir du 9 juin 1572 sous le nom d'Henri III, et roi de France sous le nom d'Henri IV du 2 août 1589 jusqu'à sa mort. Il réunit ainsi les dignités de roi de France et de Navarre et est le premier monarque français de la maison capétienne de Bourbon.",118,"fr:Henri_IV_(roi_de_France)","c:9/97/Henri_IV_portant_la_croix_du_Saint-Esprit_-_Frans_Pourbus_le_Jeune.jpg"],["Q38370",239,"monarque","Henri VIII","L","Henri VIII, né le 28 juin 1491 à Greenwich et mort le 28 janvier 1547 à Londres, est roi d'Angleterre et d'Irlande de 1509 à sa mort, ainsi que fondateur de l'Église anglicane.",117,"fr:Henri_VIII","c:8/81/Enrique_VIII_de_Inglaterra%2C_por_Hans_Holbein_el_Joven.jpg"],["Q7996",241,"monarque","Ivan le Terrible","PC","Ivan IV Vassiliévitch, dit Ivan le Terrible, né le 25 août 1530 à Kolomenskoïe, près de Moscou, et mort le 28 mars 1584 à Moscou, grand-prince de Vladimir et de Moscou de 1533 à 1584, est le premier tsar de Russie de 1547 à sa mort. De tous les souverains russes, il eut le plus long règne.",119,"fr:Ivan_le_Terrible","c:f/f4/Ivan_grozny_frame.jpg"],["Q79972",242,"monarque","Jacques VI et Ier","R","Jacques Stuart, né le 19 juin 1566 au château d'Édimbourg et mort le 27 mars 1625 à Theobalds House, est roi d'Écosse sous le nom de Jacques VI à partir du 24 juillet 1567, ainsi que roi d'Angleterre et d'Irlande sous le nom de Jacques Ier à partir du 24 mars 1603. Jacques Stuart règne jusqu'à sa mort en union personnelle sur les trois royaumes, qui conservent néanmoins leur indépendance et leurs institutions propres.",117,"fr:Jacques_VI_et_Ier","c:7/72/James_I_of_England_by_Daniel_Mytens.jpg"],["Q57376",243,"monarque","Jigme Khesar Wangchuck","C","Jigme Khesar Wangchuck, en dzongkha: འཇིགས་མེད་གེ་སར་རྣམ་རྒྱལ་དབང་ཕྱུག་, né le 21 février 1980 à Katmandou, est le roi du Bhoutan et le cinquième monarque de la dynastie Wangchuck. Il est roi depuis le 14 décembre 2006, couronné en 2008. À cette date, il était le plus jeune roi au monde.",118,"fr:Jigme_Khesar_Wangchuck","c:6/6b/Jigme_Khesar_Namgyel_Wangchuck_at_the_Enthronement_of_Naruhito.jpg"],["Q19943",244,"monarque","Juan Carlos Ier","PC","Juan Carlos Ier, né le 5 janvier 1938 à Rome, est un monarque et un homme d'État espagnol, roi d'Espagne du 22 novembre 1975 jusqu'à son abdication le 18 juin 2014.",119,"fr:Juan_Carlos_Ier","c:9/9e/Rey_Juan_Carlos_2013.jpg"],["Q346",245,"monarque","Louis IX","C","Louis IX, parfois dit « le Prud'homme » et plus communément appelé Saint Louis, est un roi de France capétien, né le 25 avril 1214 à Poissy et mort le 25 août 1270 à Carthage, près de Tunis. Il régna pendant plus de 43 ans, de 1226 jusqu'à sa mort. Considéré comme un saint de son vivant, il est canonisé par l'Église catholique dès 1297.",119,"fr:Louis_IX","c:d/de/Saintlouis_%28cropped%29.jpg"],["Q7738",246,"monarque","Louis XV","PC","Louis XV, dit « le Bien-Aimé », né le 15 février 1710 à Versailles et mort le 10 mai 1774 dans la même ville, est un roi de France et de Navarre. Membre de la maison de Bourbon, il règne sur le royaume de France du 1er septembre 1715 à sa mort. Il est le seul roi de France à naître et mourir au château de Versailles.",116,"fr:Louis_XV","c:7/78/Louis_XV_France_by_Louis-Michel_van_Loo_002.jpg"],["Q7732",247,"monarque","Louis XVI","R","Louis XVI, né le 23 août 1754 au château de Versailles sous le nom de Louis-Auguste de France et mort guillotiné le 21 janvier 1793 à Paris, est roi de France et de Navarre du 10 mai 1774 au 14 septembre 1791, puis roi des Français du 14 septembre 1791 au 21 septembre 1792.",118,"fr:Louis_XVI","c:d/dd/Louis_XVI_en_costume_de_sacre_-_Joseph-Siffred_Duplessis.jpg"],["Q102139",251,"monarque","Margrethe II","C","Margrethe II, en français Marguerite II, née le 16 avril 1940 à Copenhague, est la reine de Danemark du 14 janvier 1972 au 14 janvier 2024.",119,"fr:Margrethe_II","c:e/e5/Drottning_Margrethe_av_Danmark.jpg"],["Q47365",252,"monarque","Marie-Antoinette d'Autriche","E","Marie-Antoinette Josèphe Jeanne de Habsbourg-Lorraine, archiduchesse d'Autriche, princesse de Bohême et de Hongrie, née le 2 novembre 1755 à Vienne en Autriche, est reine de France et de Navarre de 1774 à 1791, puis reine des Français de 1791 à 1792. Dernière reine de l'Ancien Régime, elle meurt guillotinée le 16 octobre 1793 sur la place de la Révolution à Paris.",119,"fr:Marie-Antoinette_d'Autriche","c:b/b9/Marie-Antoinette%3B_koningin_der_FransenFXD.jpg"],["Q131706",253,"monarque","Marie-Thérèse d'Autriche","C","Marie-Thérèse Walburge Amélie Christine de Habsbourg, née le 13 mai 1717 à Vienne, où elle est morte le 29 novembre 1780, est la dernière représentante de la maison de Habsbourg et la fondatrice - avec son époux François III, duc de Lorraine et de Bar - de la maison de Habsbourg-Lorraine.",115,"fr:Marie-Thérèse_d'Autriche_(1717-1780)","c:3/3e/Kaiserin_Maria_Theresia_%28HRR%29.jpg"],["Q34503",255,"monarque","Mehmed II","C","Mehmed II, né le 30 mars 1432 à Edirne et mort le 3 mai 1481 à Tekfu Çayiri, près de Gebze, est le septième sultan de l'Empire ottoman, d'abord entre 1444 et 1446 puis de nouveau à partir de 1451, et l'un des plus célèbres. Appelé Mehmet II ou Mahomet II dans les sources traditionnelles françaises, il est le quatrième fils de Mourad II. Par la prise de Constantinople en 1453, Mehmed II gagne les surnoms de Mehmed le Conquérant, Mehmed le Grand et de « Père de la Victoire ».",117,"fr:Mehmed_II","c:6/6e/Bellini%2C_Gentile_-_Sultan_Mehmet_II.jpg"],["Q128245",257,"monarque","Mohammad Reza Pahlavi","PC","Mohammad Reza Pahlavi dit Aryamehr ou Shahanshah, né le 26 octobre 1919 à Téhéran et mort le 27 juillet 1980 au Caire, est le second et dernier monarque de la dynastie Pahlavi ayant regné en Iran. Dernier chah d'Iran, il règne du 16 septembre 1941 au 11 février 1979. Contraint par la révolution iranienne à l'exil le 16 janvier 1979, Mohammad Reza Pahlavi est remplacé par un conseil royal puis définitivement renversé, mais n'abdiquera jamais officiellement.",118,"fr:Mohammad_Reza_Pahlavi","c:6/6c/Shah_Mohammad_Reza_Pahlavi%2C_1973.jpg"],["Q12591",259,"monarque","Nabuchodonosor II","C","Nabuchodonosor II (babylonien: Nabû-kudurrī-uṣur; araméen: ܢ ܵܒܘ ܟܘ ܕܘ ܼܪܝ ܼܘܨܘܪ; hébreu: נְבוּכַדְנֶאצַּר / Nəḇūḵhaḏnatṣṣar; grec ancien: Ναϐουχοδονόσωρ / Naboukhodonósôr; arabe: نَبُوخَذ نَصر / Nibūkḫaḏnaṣṣar) est le roi de l'Empire néo-babylonien entre 605 et 562 av. J.-C.",108,"fr:Nabuchodonosor_II","c:3/3a/Nebuchadnezzar_II_cylinder.jpg"],["Q7721",260,"monarque","Napoléon III","R","Louis-Napoléon Bonaparte, né le 20 avril 1808 à Paris et mort le 9 janvier 1873 à Chislehurst, est un monarque et homme d'État français. Il est à la fois l'unique président de la Deuxième République, le premier chef d'État français élu au suffrage universel masculin le 10 décembre 1848, le premier président de la République française et, après la proclamation de l'Empire le 2 décembre 1852, le dernier monarque du pays en tant qu'empereur des Français sous le nom de Napoléon III.",119,"fr:Napoléon_III","c:c/cf/Napol%C3%A9on_III_par_Jean_Hippolyte_Flandrin.jpg"],["Q40787",262,"monarque","Nicolas II","PC","Nicolas II, né Nikolaï Alexandrovitch Romanov le 6 mai 1868 au palais de Tsarskoïe Selo et assassiné le 17 juillet 1918 à Iekaterinbourg, est un empereur de Russie de la dynastie des Romanov. Il est « tsar de toutes les Russies » du 1er novembre 1894 à son abdication le 15 mars 1917, ainsi que roi de Pologne et grand-duc de Finlande.",119,"fr:Nicolas_II","c:b/b6/Nicholas_II%2C_Russian_Emperor_%28cropped_2%29.jpg"],["Q40930",263,"monarque","Néfertiti","C","Néfertiti est une reine d'Égypte, grande épouse royale d'Akhenaton, l'un des derniers rois de la XVIIIe dynastie. Elle a vécu aux environs de 1370 à 1333 av. J.-C.","Néfertiti est une reine d'Égypte, grande épouse royale d'Akhenaton, l'un des derniers rois de la XVIIIe dynastie.","fr:Néfertiti","c:1/1f/Nofretete_Neues_Museum.jpg"],["Q34428",265,"monarque","Philippe II Auguste","C","Philippe II dit « Auguste » né le 21 août 1165 à Paris et mort à Mantes le 14 juillet 1223, est le septième roi de la dynastie des Capétiens et le premier monarque auquel est attribué le titre de roi de France. Il est le fils héritier de Louis VII et d'Adèle de Champagne.",117,"fr:Philippe_II_Auguste","c:d/dc/Sceau_de_Philippe_Auguste._-_Archives_Nationales_-_SC-D157.jpg"],["Q8479",266,"monarque","Pierre Ier le Grand","R","Pierre Ier, plus connu sous le nom de Pierre le Grand, né le 30 mai 1672 à Moscou et mort le 28 janvier 1725 à Saint-Pétersbourg, devient tsar de Russie en 1682 et reçoit le titre d'empereur de toutes les Russies en 1721.",110,"fr:Pierre_Ier_le_Grand","c:7/72/Peter_der-Grosse_1838.jpg"],["Q855252",267,"monarque","Rama IX","PC","Bhumibol Adulyadej, né le 5 décembre 1927 à Cambridge et mort le 13 octobre 2016 à Bangkok, couronné en 1950 sous le nom dynastique de Rama IX, est roi de Thaïlande de 1946 à sa mort. Monarque constitutionnel, il est le chef de l'État et protecteur des religions de Thaïlande.",116,"fr:Rama_IX","c:2/22/Bhumibol_Adulyadej_2010-9-29_2_cropped.jpg"],["Q548733",268,"monarque","Rama X","R","Vajiralongkorn, né le 28 juillet 1952 à Bangkok, est roi de Thaïlande, sous le nom de Rama X, depuis le 1er décembre 2016.",116,"fr:Rama_X","c:7/74/King_Rama_X_official_%28crop%29_%28cropped%29.png"],["Q1523",269,"monarque","Ramsès II","PC","Ramsès II, né aux alentours de 1304 / 1301 av. J.-C. et mort à Pi-Ramsès vers 1213 av. J.-C., est le troisième pharaon de la XIXe dynastie égyptienne, au Nouvel Empire. Il est aussi appelé « Ramsès le Grand » ou encore « Ozymandias ». Manéthon l'appelle « Ramsès ».","Ramsès II, né aux alentours de 1304 / 1301 av.","fr:Ramsès_II","c:c/c8/Le_mus%C3%A9e_%C3%A9gyptien_%28Turin%29_%282866334984%29.jpg"],["Q42305",270,"monarque","Richard Cœur de Lion","PC","Richard Ier dit Cœur de Lion, né le 8 septembre 1157 au palais de Beaumont à Oxford, et mort le 6 avril 1199 au siège du château de Châlus-Chabrol, est roi d'Angleterre, duc de Normandie, comte du Maine et comte d'Anjou de 1189 à sa mort, et duc d'Aquitaine et comte de Poitiers dès 1171 ou 1172.",117,"fr:Richard_Cœur_de_Lion","c:6/6b/Church_of_Fontevraud_Abbey_Richard_I_effigy.jpg"],["Q367825",271,"monarque","Salmane ben Abdelaziz Al Saoud","R","Salmane ben Abdelaziz Al Saoud ou, de manière plus courte, Salmane, né le 31 décembre 1935 à Riyad, est roi d'Arabie saoudite depuis le 23 janvier 2015.",116,"fr:Salmane_ben_Abdelaziz_Al_Saoud","c:0/03/Salman_of_Saudi_Arabia_-_2020_%2849563590728%29_%28cropped%29.jpg"],["Q83672",272,"monarque","Shâh Jahân","C","Shahab-ud-din Muhammad Khurram, plus connu sous son nom de règne Shâh Jahân, né le 5 janvier 1592 à Lahore et mort le 22 janvier 1666 au Fort d'Agra à Agra, est le cinquième empereur moghol. Son règne s'étend du 19 janvier 1628 au 31 juillet 1658.",117,"fr:Shâh_Jahân","c:3/3c/Indian_-_Single_Leaf_of_a_Portrait_of_Shah_Jahan_-_Walters_W700_-_Detail.jpg"],["Q12154",273,"monarque","Toutânkhamon","PC","Toutânkhamon, né vers 1345 av. J.-C. et mort vers 1327, est le onzième pharaon de la XVIIIe dynastie. Selon les dernières études génétiques, il est le fils de la momie trouvée dans la tombe KV55 et de la propre sœur de ce dernier, dont l'identité est inconnue, désignée comme Younger Lady, dont la momie est répertoriée KV35YL. Manéthon l'appelle Χέϐρης / Khébrês.","Toutânkhamon, né vers 1345 av.","fr:Toutânkhamon","c:f/f5/Mask_of_Tutankhamun_2003-12-07.jpg"],["Q9439",274,"monarque","Victoria","E","Victoria, née Alexandrina Victoria le 24 mai 1819 au palais de Kensington à Londres et morte le 22 janvier 1901 à Osborne House sur l'île de Wight, est reine du Royaume-Uni de Grande-Bretagne et d'Irlande du 20 juin 1837 jusqu'à sa mort. À partir du 1er juillet 1867, elle est également reine du Canada, ainsi qu'impératrice des Indes à compter du 1er mai 1876, puis enfin reine d'Australie le 1er janvier 1901.",113,"fr:Victoria_(reine)","c:d/de/Queen_Victoria_-_Winterhalter_1859.jpg"],["Q154952",275,"monarque","Willem-Alexander","C","Willem-Alexander, parfois francisé en Guillaume-Alexandre, né le 27 avril 1967 à Utrecht, est roi des Pays-Bas depuis le 30 avril 2013.",117,"fr:Willem-Alexander","c:1/18/Zijne_Majesteit_Koning_Willem-Alexander_met_koningsmantel_april_2013_%28cropped%29.jpeg"],["Q83229",276,"monarque","Édouard VI","PC","Édouard VI, né le 12 octobre 1537 à Londres et mort le 6 juillet 1553 à Greenwich, est roi d'Angleterre et d'Irlande de 1547 à sa mort. Il est couronné le 20 février 1547 à l'âge de neuf ans, ce qui en fait l'un des plus jeunes souverains anglais. Il est le fils d'Henri VIII et de Jeanne Seymour, et devient le troisième souverain de la dynastie des Tudor ainsi que le premier souverain anglais né anglican à monter sur le trône.",119,"fr:Édouard_VI","c:e/e5/Circle_of_William_Scrots_Edward_VI_of_England.jpg"],["Q20875",277,"monarque","Édouard VII","R","Édouard VII, né Albert Edward le 9 novembre 1841 à Londres au palais de Buckingham où il est mort le 6 mai 1910, est roi du Royaume-Uni et des dominions ainsi qu'empereur des Indes du 22 janvier 1901 jusqu'à sa mort.",116,"fr:Édouard_VII","c:8/88/King_Edward_VII_by_Sir_%28Samuel%29_Luke_Fildes.jpg"],["Q590227",278,"monarque","Édouard VIII","E","Édouard VIII, né le 23 juin 1894 à Londres et mort le 28 mai 1972 à Paris, est roi du Royaume-Uni et des autres dominions du Commonwealth britannique, ainsi qu'empereur des Indes du 20 janvier au 11 décembre 1936.",111,"fr:Édouard_VIII","c:e/ee/King_Edward_VIII.png"],["Q9682",279,"monarque","Élisabeth II","L","Élisabeth II, née le 21 avril 1926 à Londres et morte le 8 septembre 2022 au château de Balmoral, est reine du Royaume-Uni de Grande-Bretagne et d'Irlande du Nord et des autres royaumes du Commonwealth du 6 février 1952 à sa mort.",110,"fr:Élisabeth_II","c:6/68/Elizabeth_II_in_Berlin_2015_%28cropped%29.JPG"],["Q7207",280,"monarque","Élisabeth Ire","E","Élisabeth Ire, née le 7 septembre 1533 au palais de Placentia à Londres et morte le 24 mars 1603 au palais de Richmond dans la même ville, est reine d'Angleterre et d'Irlande de 1558 à sa mort.",118,"fr:Élisabeth_Ire_(reine_d'Angleterre)","c:e/e5/Elizabeth1England.jpg"],["Q49766",281,"parti","Alliance 90/Les Verts","C","L’Alliance 90/Les Verts est un parti politique allemand écologiste de centre gauche. Fondé en 1980 en Allemagne de l'Ouest sous le nom de Les Verts, il fait son entrée au Bundestag à l'occasion des élections fédérales de 1983. Il fusionne en 1993 avec l'Alliance 90, formation fondée en Allemagne de l'Est en 1990 à la suite de la chute du mur de Berlin et issue de l’opposition au régime communiste.","L’Alliance 90/Les Verts est un parti politique allemand écologiste de centre gauche.","fr:Alliance_90/Les_Verts","https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/B%C3%BCndnis_90_-_Die_Gr%C3%BCnen_Logo_%28transparent%29.svg/330px-B%C3%BCndnis_90_-_Die_Gr%C3%BCnen_Logo_%28transparent%29.svg.png"],["Q6721203",282,"parti","Alternative pour l'Allemagne","R","L'Alternative pour l'Allemagne est un parti politique allemand d'extrême droite. L'AfD est connu pour son opposition à l'Union européenne et à l'immigration en Allemagne. Il est créé le 6 février 2013 et lancé officiellement le 14 avril 2013 à Berlin avec une orientation eurosceptique et nationaliste.","L'Alternative pour l'Allemagne est un parti politique allemand d'extrême droite.","fr:Alternative_pour_l'Allemagne","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/AfD_Logo_2021.svg/330px-AfD_Logo_2021.svg.png"],["Q10230",283,"parti","Bharatiya Janata Party","PC","Le Bharatiya Janata Party ou BJP est un des deux principaux partis politiques indiens. Créé en 1980, le BJP est un parti d'extrême droite nationaliste hindou considéré comme l'aile politique du Rashtriya Swayamsevak Sangh. C'est le principal parti de l'Alliance démocratique nationale: une coalition au pouvoir de 1998 à 2004 et de nouveau depuis 2014. Avec plus de 180 millions d'adhérents en date d'avril 2022, c’est le plus grand parti politique du monde.","Le Bharatiya Janata Party ou BJP est un des deux principaux partis politiques indiens.","fr:Bharatiya_Janata_Party","https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Logo_of_the_Bharatiya_Janata_Party.svg/330px-Logo_of_the_Bharatiya_Janata_Party.svg.png"],["Q83162",284,"parti","Congrès national africain","C","Le Congrès national africain est un parti politique d’Afrique du Sud membre de l'Internationale socialiste. Fondé en 1912 à Bloemfontein pour défendre les intérêts de la majorité noire contre la minorité blanche, il fut déclaré hors-la-loi par le Parti national pendant l’apartheid en 1960. Il est à nouveau légalisé le 2 février 1990 alors que l’apartheid est aboli en juin 1991. Il aura également été classé comme organisation terroriste par les États-Unis de 1986 à 2008.","Le Congrès national africain est un parti politique d’Afrique du Sud membre de l'Internationale socialiste.","fr:Congrès_national_africain","https://upload.wikimedia.org/wikipedia/fr/thumb/7/7a/ANC_congr%C3%A8s_national_africain_logo.svg/330px-ANC_congr%C3%A8s_national_africain_logo.svg.png"],["Q10225",285,"parti","Congrès national indien","PC","Le Congrès national indien est l'un des principaux partis politiques d'Inde.",null,"fr:Congrès_national_indien","https://upload.wikimedia.org/wikipedia/fr/thumb/f/fe/INC.png/330px-INC.png"],["Q49764",286,"parti","Die Linke","C","Die Linke, en français « La Gauche », est un parti politique allemand né de la fusion le 15 juin 2007 du Parti du socialisme démocratique et de l'Alternative électorale travail et justice sociale.",113,"fr:Die_Linke","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d6/Logo_Die_Linke_%282023%29.svg/330px-Logo_Die_Linke_%282023%29.svg.png"],["Q156874",287,"parti","Droit et justice","C","Droit et justice est un parti politique polonais, fondé en 2001 par les frères Jarosław et Lech Kaczyński.",null,"fr:Droit_et_justice","https://upload.wikimedia.org/wikipedia/fr/thumb/1/19/Logo_PiS_jasne.svg/330px-Logo_PiS_jasne.svg.png"],["Q655611",288,"parti","Ecolo","C","Ecolo, en forme longue Écologistes confédérés pour l'organisation de luttes originales, est un parti politique belge de gauche, présent en Belgique francophone et germanophone, qui se réclame de l'écologie politique et suit certains des principes de la politique écologique. Son pendant flamand est Groen.",119,"fr:Ecolo","c:2/28/Rue_de_Marvis_%28Tournai%29.jpg"],["Q178888",289,"parti","Fatah","C","Le Fatah est un parti politique nationaliste palestinien qui est le plus important de l'Organisation de libération de la Palestine et le deuxième du Conseil législatif palestinien. Fondé par Yasser Arafat, Khaled Yashruti, Salah Khalaf et Khalil al-Wazir au Koweït en 1959.",117,"fr:Fatah","c:d/dc/Fatah_Flag_Vector_Graphic.png"],["Q133207",290,"parti","Frères musulmans","R","La Société des Frères musulmans, est une organisation transnationale islamiste sunnite fondée en 1928 par Hassan el-Banna à Ismaïlia, dans le nord-est de l'Égypte. Cette organisation panislamiste conservatrice est considérée comme terroriste par plusieurs pays (Égypte, Arabie saoudite, Russie, Émirats arabes unis, Syrie, Bahreïn, Jordanie).",112,"fr:Frères_musulmans","https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Flag_of_the_Muslim_Brotherhood_%28darker%29.svg/330px-Flag_of_the_Muslim_Brotherhood_%28darker%29.svg.png"],["Q41053",291,"parti","Hezbollah","C","Le Hezbollah, aussi appelé le Parti de Dieu, est un parti politique et un groupe paramilitaire islamiste chiite libanais.",111,"fr:Hezbollah","https://upload.wikimedia.org/wikipedia/fr/thumb/d/df/Drapeau_du_Hezbollah.svg/330px-Drapeau_du_Hezbollah.svg.png"],["Q31113",292,"parti","Kuomintang","PC","Le Kuomintang, Guomindang, Kuo-Min-Tang, ou Kouo-Min-Tang est le plus ancien parti politique de la Chine contemporaine et présent à Taïwan. Créé en 1912 par Sun Yat-sen, il domine le gouvernement central de la république de Chine à partir de 1928 jusqu'à la prise de pouvoir par les communistes en 1949.",118,"fr:Kuomintang","https://upload.wikimedia.org/wikipedia/commons/thumb/a/a1/Emblem_of_the_Kuomintang.svg/330px-Emblem_of_the_Kuomintang.svg.png"],["Q27978402",293,"parti","La France insoumise","L","La France insoumise est un parti politique français fondé par Jean-Luc Mélenchon le 10 février 2016. Souvent considéré comme relevant de la gauche radicale, il est classé à la gauche de l'échiquier politique, voire à l'extrême gauche. Ses membres promeuvent un programme écosocialiste tout en tenant un discours anticapitaliste et antilibéral, ainsi qu'en défendant le non-alignement à l'international.","La France insoumise est un parti politique français fondé par Jean-Luc Mélenchon le 10 février 2016.","fr:La_France_insoumise","c:7/71/LOGO-LFI-2026.png",{"cats":["politique","politique_fr"]}],["Q111518329",294,"parti","Les Engagés","C","Les Engagés peuvent désigner:",null,"fr:Les_Engagés",""],["Q20012759",295,"parti","Les Républicains","E","Les Républicains sont un parti politique français, classé à droite sur l'échiquier politique, issu de la transformation en 2015 de l'Union pour un mouvement populaire, fondée en 2002, sous l'impulsion de l'ancien président de la République Nicolas Sarkozy. Il s'inscrit dans la continuité des grands partis conservateurs et gaullistes français: l'UNR, l'UDR, le RPR et l'UMP.",119,"fr:Les_Républicains","https://upload.wikimedia.org/wikipedia/fr/thumb/2/2c/Logo_Les_R%C3%A9publicains_-_2023.svg/330px-Logo_Les_R%C3%A9publicains_-_2023.svg.png",{"cats":["politique","politique_fr"]}],["Q613786",296,"parti","Les Écologistes","PC","Les Écologistes, dénommé Europe Écologie Les Verts jusqu'en 2023, est un parti politique écologiste et eurofédéraliste français. Issu en 2010 du changement de nom du parti Les Verts, il vise alors à rassembler les militants venus des listes Europe Écologie aux élections européennes de 2009 et régionales de 2010.",118,"fr:Les_Écologistes","",{"cats":["politique","politique_fr"]}],["Q9624",297,"parti","Libéraux-démocrates britanniques","C","Les Libéraux-démocrates sont un parti politique britannique classé du centre au centre gauche de l'échiquier politique.",null,"fr:Libéraux-démocrates_(Royaume-Uni)","https://upload.wikimedia.org/wikipedia/fr/thumb/6/62/Liberal_Democrats_logo.svg/330px-Liberal_Democrats_logo.svg.png"],["Q187009",298,"parti","Likoud","E","Le Likoud est un parti politique israélien généralement classé à droite, voire à l’extrême droite.",null,"fr:Likoud","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b6/Flag_of_the_Likud.svg/330px-Flag_of_the_Likud.svg.png"],["Q47817",299,"parti","Mouvement 5 étoiles","C","Le Mouvement 5 étoiles est un parti politique italien fondé en 2009 par Beppe Grillo et Gianroberto Casaleggio et dirigé depuis le 6 août 2021 par Giuseppe Conte.",113,"fr:Mouvement_5_étoiles","https://upload.wikimedia.org/wikipedia/commons/thumb/5/55/M5S_logo_2050.svg/330px-M5S_logo_2050.svg.png"],["Q531853",300,"parti","Mouvement réformateur","C","Le Mouvement réformateur est un parti politique belge libéral.",null,"fr:Mouvement_réformateur",""],["Q28982",301,"parti","Nieuw-Vlaamse Alliantie","C","La Nieuw-Vlaamse Alliantie ou N-VA est un parti politique belge nationaliste flamand de centre droit à droite, né de la dislocation de la Volksunie en 2001.",119,"fr:Nieuw-Vlaamse_Alliantie","c:8/87/N-va_vlag.png"],["Q179933",302,"parti","Parti Baas","C","Le Parti Baas, ou Baath, et plus fidèlement, Ba'th, de son nom complet le Parti socialiste de la résurrection arabe, est un parti politique créé en 1944 en Syrie avec comme but l'unification des différents États arabes en une seule et grande nation.",116,"fr:Parti_Baas","https://upload.wikimedia.org/wikipedia/commons/thumb/a/ab/Syrian_Baath_Logo.svg/330px-Syrian_Baath_Logo.svg.png"],["Q17427",303,"parti","Parti communiste chinois","PC","Le Parti communiste chinois, est un parti politique chinois fondé en 1921. Vainqueur de la guerre civile chinoise, il dirige la république populaire de Chine depuis la fondation de celle-ci en 1949, et constitue de facto le parti unique du pays. Depuis son accession au pouvoir, le PCC contrôle la politique de la Chine à tous les niveaux.","Le Parti communiste chinois, est un parti politique chinois fondé en 1921.","fr:Parti_communiste_chinois","https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Danghui.svg/330px-Danghui.svg.png"],["Q192187",304,"parti","Parti communiste de la fédération de Russie","C","Le Parti communiste de la fédération de Russie (en abrégé PCFR; en russe Коммунистическая партия Российской Федерации, КПРФ) est un parti politique russe.",118,"fr:Parti_communiste_de_la_fédération_de_Russie","https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/KPRF_Logo.svg/330px-KPRF_Logo.svg.png"],["Q192821",305,"parti","Parti communiste français","R","Le Parti communiste français est un parti politique français fondé en 1920. Il est issu du congrès de Tours de la Section française de l'Internationale ouvrière dont l'objet est l'adhésion à l'Internationale communiste; la majorité du congrès étant en faveur de cette adhésion crée alors la Section française de l'Internationale communiste, la minorité restant au sein de la SFIO.","Le Parti communiste français est un parti politique français fondé en 1920.","fr:Parti_communiste_français","https://upload.wikimedia.org/wikipedia/fr/thumb/6/6a/Logo_du_Parti_communiste_fran%C3%A7ais_%282018%2C_rouge%29.svg/330px-Logo_du_Parti_communiste_fran%C3%A7ais_%282018%2C_rouge%29.svg.png",{"cats":["politique","politique_fr"]}],["Q9626",306,"parti","Parti conservateur britannique","C","Le Parti conservateur, officiellement Parti conservateur et unioniste, est un parti politique britannique conservateur, habituellement classé à droite. Ses membres sont famillièrement appelés les Tories.",119,"fr:Parti_conservateur_(Royaume-Uni)","c:7/7e/Conservative_Party_conference_2011.jpg"],["Q19077",307,"parti","Parti de la justice et du développement","C","Le Parti de la justice et du développement, AK PARTİ ou AKP est un parti islamo-conservateur, au pouvoir en Turquie depuis 2002. Recep Tayyip Erdoğan en est le président général depuis le 21 mai 2017, désigné lors d'un congrès extraordinaire à Ankara. Il succède à Binali Yıldırım.",115,"fr:Parti_de_la_justice_et_du_développement_(Turquie)","https://upload.wikimedia.org/wikipedia/fr/thumb/0/02/Justice_and_Development_Party.png/330px-Justice_and_Development_Party.png"],["Q131692",308,"parti","Parti de la liberté d'Autriche","C","Le Parti de la liberté d'Autriche ou Parti libéral autrichien est un parti politique autrichien d'extrême droite et de droite populiste fondé en 1956. Il est présidé depuis 2021 par Herbert Kickl.",118,"fr:Parti_de_la_liberté_d'Autriche","https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Logo_of_Freedom_Party_of_Austria.svg/330px-Logo_of_Freedom_Party_of_Austria.svg.png"],["Q925616",309,"parti","Parti du travail de Belgique","C","Le Parti du travail de Belgique est un parti politique belge national et unitaire, c'est-à-dire non divisé selon le clivage linguistique, fondé en 1979. Le PTB s'identifie comme un parti marxiste, anticapitaliste. Il est généralement décrit comme de gauche radicale ou d'extrême gauche.",115,"fr:Parti_du_travail_de_Belgique","c:c/cf/PTB-logo.png"],["Q49623",310,"parti","Parti du travail de Corée","C","Le Parti du travail de Corée, également traduit en Parti des travailleurs de Corée, ou plus rarement Parti ouvrier de Corée, est le parti politique au pouvoir en Corée du Nord depuis 1949. Son idéologie officielle est le juche.",117,"fr:Parti_du_travail_de_Corée","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/WPK_symbol.svg/330px-WPK_symbol.svg.png"],["Q29552",311,"parti","Parti démocrate américain","R","Le Parti démocrate est l'un des deux principaux partis politiques américains contemporains. Dans le cadre du système bipartite américain, il s'oppose au Parti républicain, avec lequel il domine la vie politique nationale depuis les années 1860. Il est l'une des plus grandes organisations politiques mondiales avec près de 46 millions d'adhérents en 2023.","Le Parti démocrate est l'un des deux principaux partis politiques américains contemporains.","fr:Parti_démocrate_(États-Unis)",""],["Q47729",312,"parti","Parti démocrate italien","C","Le Parti démocrate est un parti politique italien, classé en général au centre gauche. Fondé le 14 octobre 2007, le PD réunit des courants issus de la gauche anciennement communiste et de la démocratie chrétienne.","Le Parti démocrate est un parti politique italien, classé en général au centre gauche.","fr:Parti_démocrate_(Italie)","https://upload.wikimedia.org/wikipedia/fr/thumb/9/9e/Partito_democratico_logo.png/330px-Partito_democratico_logo.png"],["Q19683",313,"parti","Parti indépendantiste portoricain","C","Le Parti indépendantiste portoricain est un parti politique portoricain qui fait campagne pour l'indépendance de Porto Rico face aux États-Unis d'Amérique. Il est l'un des trois principaux partis politiques et le deuxième plus vieux parti de Porto Rico.",118,"fr:Parti_indépendantiste_portoricain","c:5/57/PIP_new_logo.png"],["Q138345",314,"parti","Parti libéral du Canada","C","Le Parti libéral du Canada est un parti politique fédéral canadien. Ses membres sont appelés les libéraux, et anciennement surnommés les Grits. Le parti, dirigé par Mark Carney, forme le gouvernement au Parlement du Canada. Il possède 174 sièges à la Chambre des communes, mais aucun au Sénat, le premier ministre ayant coupé les liens avec les sénateurs libéraux dans le but de donner davantage d'indépendance à la chambre haute.","Le Parti libéral du Canada est un parti politique fédéral canadien.","fr:Parti_libéral_du_Canada","https://upload.wikimedia.org/wikipedia/fr/thumb/b/b1/Logo_PLC.svg/330px-Logo_PLC.svg.png"],["Q13124",315,"parti","Parti libéral-démocrate allemand","C","Le Parti libéral-démocrate est un parti politique libéral allemand créé en 1948.",null,"fr:Parti_libéral-démocrate_(Allemagne)","https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Logo_der_FDP_2026.svg/330px-Logo_der_FDP_2026.svg.png"],["Q232595",316,"parti","Parti libéral-démocrate japonais","C","Le Parti libéral-démocrate, souvent abrégé en Jimintō au Japon et PLD en français, est le plus important parti politique japonais, et la principale force de droite et conservatrice du pays. Il a pratiquement toujours gouverné le pays depuis sa création en 1955, sauf pendant un intermède de dix mois entre 1993 et 1994, et pendant trois ans après sa défaite aux élections législatives du 30 août 2009.",110,"fr:Parti_libéral-démocrate_(Japon)","https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Liberal_Democratic_Party_%28Japan%29_Emblem.svg/330px-Liberal_Democratic_Party_%28Japan%29_Emblem.svg.png"],["Q139596",317,"parti","Parti national fasciste","C","Le Parti national fasciste était le parti politique italien qui représentait l'idéologie fasciste. Fondé le 9 novembre 1921 par Benito Mussolini, il trouve ses origines dans les faisceaux italiens de combat, créés en mars 1919 alors que le royaume d'Italie est en proie à des troubles économiques et sociaux, liés à la sortie de la Première Guerre mondiale.","Le Parti national fasciste était le parti politique italien qui représentait l'idéologie fasciste.","fr:Parti_national_fasciste","https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/National_Fascist_Party_logo.svg/330px-National_Fascist_Party_logo.svg.png"],["Q10658",318,"parti","Parti national écossais","C","Le Parti national écossais est le principal parti nationaliste et indépendantiste écossais.",null,"fr:Parti_national_écossais",""],["Q204911",319,"parti","Parti ouvrier social-démocrate de Russie","C","Le Parti ouvrier social-démocrate de Russie, officiellement le Parti ouvrier social-démocrate russe, également traduit Parti social-démocrate des Travailleurs de Russie, et nommé plus simplement Parti social-démocrate de Russie, est un ancien parti politique russe fondé en 1898 à Minsk. De tendance socialiste et marxiste révolutionnaire, il s'inscrit dans le contexte de l'Internationale ouvrière et avait pour objectif de renverser le régime tsariste afin d'instaurer un État socialiste.",118,"fr:Parti_ouvrier_social-démocrate_de_Russie","c:7/75/1st_Programme_of_the_Russian_Social_Democratic_Labour_Party.jpg"],["Q185088",320,"parti","Parti populaire espagnol","PC","Le Parti populaire est un parti politique espagnol libéral-conservateur.",null,"fr:Parti_populaire_(Espagne)","https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Logo_del_PP_%282022%29.svg/330px-Logo_del_PP_%282022%29.svg.png"],["Q23731823",321,"parti","Parti Renaissance","E","Renaissance, dénommé En marche de 2016 à 2017, puis La République en marche jusqu'en 2022, est un parti politique français créé en avril 2016 par Emmanuel Macron. Le parti a dirigé la coalition Ensemble pour la République pour les élections législatives de 2022 et de 2024.",113,"fr:Renaissance_(parti)","https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/Renaissance-logotype-officiel.svg/330px-Renaissance-logotype-officiel.svg.png",{"cats":["politique","politique_fr"]}],["Q29468",322,"parti","Parti républicain américain","R","Le Parti républicain, également surnommé en anglais Grand Old Party, est l'un des deux principaux partis politiques américains contemporains. Dans le cadre du système bipartite américain, il s'oppose au Parti démocrate, avec lequel il domine la vie politique nationale depuis les années 1860. Il est l'une des plus grandes organisations politiques mondiales avec près de 36 millions d'adhérents en 2023.",115,"fr:Parti_républicain_(États-Unis)",""],["Q19079",323,"parti","Parti républicain du peuple","C","Le Parti républicain du peuple est un parti politique turc, de type républicain, social-démocrate, nationaliste et laïc, créé en 1923 par Mustafa Kemal Atatürk. Il est membre de l'Internationale socialiste et membre associé du Parti socialiste européen.",114,"fr:Parti_républicain_du_peuple_(Turquie)","https://upload.wikimedia.org/wikipedia/commons/thumb/e/ef/Cumhuriyet_Halk_Partisi_Logo.svg/330px-Cumhuriyet_Halk_Partisi_Logo.svg.png"],["Q49768",324,"parti","Parti social-démocrate d'Allemagne","PC","Le Parti social-démocrate d’Allemagne, fondé en 1875 sous le nom de SAP et rebaptisé SPD en 1891, est un parti politique allemand social-démocrate et le plus vieux parti politique d'Allemagne. C'est le seul des grands partis actuels de la République fédérale d'Allemagne qui existait sous une forme comparable avant la Seconde Guerre mondiale. C'est, avec la CDU, le parti politique allemand ayant le plus d'adhérents avec un total de 500 000.",110,"fr:Parti_social-démocrate_d'Allemagne","https://upload.wikimedia.org/wikipedia/commons/thumb/d/df/Flag_of_the_Social_Democratic_Party_of_Germany.svg/330px-Flag_of_the_Social_Democratic_Party_of_Germany.svg.png"],["Q179111",325,"parti","Parti social-démocrate d'Autriche","C","Le Parti social-démocrate d'Autriche est un parti politique autrichien de centre gauche. Il a été fondé par Victor Adler en 1889 sous le nom de Parti ouvrier social-démocrate.","Le Parti social-démocrate d'Autriche est un parti politique autrichien de centre gauche.","fr:Parti_social-démocrate_d'Autriche","c:7/7b/SP%C3%96_Zentrale%2C_Vienna_3.jpg"],["Q105112",326,"parti","Parti social-démocrate suédois des travailleurs","C","Le Parti social-démocrate suédois des travailleurs, communément appelé « Les sociaux-démocrates », est un parti politique suédois d'orientation sociale-démocrate fondé en 1889. Il est le plus ancien ainsi que, de manière systématique depuis les élections législatives de septembre 1914, le premier parti politique en Suède. Il a gouverné le pays 80 ans en plus d'un siècle de démocratie.",111,"fr:Parti_social-démocrate_suédois_des_travailleurs","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e7/2022_Stockholm_City_Council_election_%28cropped%29.svg/330px-2022_Stockholm_City_Council_election_%28cropped%29.svg.png"],["Q645787",327,"parti","Parti socialiste belge","C","Le Parti socialiste est un parti politique belge social-démocrate classé au centre gauche et à gauche, présent en Belgique francophone.",113,"fr:Parti_socialiste_(Belgique)","https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Socialist_Party_%28Belgium%29_logo.svg/330px-Socialist_Party_%28Belgium%29_logo.svg.png"],["Q170972",328,"parti","Parti socialiste français","R","Le Parti socialiste est un parti politique français classé à gauche et au centre gauche sur l'échiquier politique.",null,"fr:Parti_socialiste_(France)","https://upload.wikimedia.org/wikipedia/fr/thumb/a/af/Logo_Parti_Socialiste_-_2024.svg/330px-Logo_Parti_Socialiste_-_2024.svg.png",{"cats":["politique","politique_fr"]}],["Q138198",329,"parti","Parti socialiste ouvrier espagnol","PC","Le Parti socialiste ouvrier espagnol est un parti politique espagnol de centre gauche social-démocrate.",null,"fr:Parti_socialiste_ouvrier_espagnol","https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Logotipo_del_PSOE.svg/330px-Logotipo_del_PSOE.svg.png"],["Q9630",330,"parti","Parti travailliste britannique","PC","Le Parti travailliste est un parti politique britannique de centre gauche. Il forme depuis le 5 juillet 2024 le gouvernement à la Chambre des communes. Il constitue également le premier parti à l'Assemblée de Londres.","Le Parti travailliste est un parti politique britannique de centre gauche.","fr:Parti_travailliste_(Royaume-Uni)","c:7/79/Keir_Starmer%2C_2020_Labour_Party_leadership_election_hustings%2C_Bristol_1.jpg"],["Q205150",331,"parti","Rassemblement national","E","Le Rassemblement national — précédemment Front national jusqu'en 2018 —, parfois surnommé le parti à la flamme, est un parti politique français d'extrême droite fondé en 1972 et successivement présidé par Jean-Marie Le Pen, Marine Le Pen et Jordan Bardella.",118,"fr:Rassemblement_national","",{"cats":["politique","politique_fr"]}],["Q151469",332,"parti","Russie unie","C","Russie unie est un parti politique russe attrape-tout fondé en 2001. Russie unie est présidé de novembre 2002 au 7 mai 2008 par Boris Gryzlov, ancien président de la Douma d’État, puis par le président du gouvernement russe, Vladimir Poutine, jusqu'en mai 2012, date à laquelle l'ancien président Dmitri Medvedev lui succède, après avoir été élu lors du XIIIe congrès du parti.","Russie unie est un parti politique russe attrape-tout fondé en 2001.","fr:Russie_unie","https://upload.wikimedia.org/wikipedia/fr/thumb/e/e6/Russie_Unie_Logo.svg/330px-Russie_Unie_Logo.svg.png"],["Q76382",333,"parti","Sinn Féin","C","Le Sinn Féin est un parti politique républicain actif en république d'Irlande et en Irlande du Nord, prônant la réunification de ces deux entités. Il s'agit du premier parti politique d'Irlande du Nord depuis les élections législatives nord-irlandaises de 2022.",111,"fr:Sinn_Féin","c:c/c2/Sinn_Fein_Advice_Centre%2C_Castlewellan%2C_December_2009.JPG"],["Q49762",334,"parti","Union chrétienne-démocrate d'Allemagne","C","L'Union chrétienne-démocrate d'Allemagne est un parti politique allemand, démocrate-chrétien, libéral-conservateur et pro-européen fondé en 1945.",117,"fr:Union_chrétienne-démocrate_d'Allemagne","https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Flag_of_CDU_2023.svg/330px-Flag_of_CDU_2023.svg.png"],["Q49763",335,"parti","Union chrétienne-sociale en Bavière","C","L’Union chrétienne-sociale en Bavière est un parti politique allemand de centre droit qui agit exclusivement en Bavière, tandis que son parti frère, l'Union chrétienne-démocrate d'Allemagne opère dans le reste du pays; la coopération des deux partis sur le plan fédéral est appelée la CDU/CSU. La CSU est plus conservatrice que la CDU. Au niveau international, elle est membre du Parti populaire européen et de l'Union démocrate internationale.",111,"fr:Union_chrétienne-sociale_en_Bavière","https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Flag_of_the_Christian_Social_Union_in_Bavaria.svg/330px-Flag_of_the_Christian_Social_Union_in_Bavaria.svg.png"],["Q682990",336,"parti","Vlaams Belang","C","Le Vlaams Belang, nommé Vlaams Blok jusqu'au 14 novembre 2004, est un parti politique belge d'extrême droite, prônant le nationalisme flamand et l'indépendance de la Flandre.",117,"fr:Vlaams_Belang","https://upload.wikimedia.org/wikipedia/fr/thumb/2/2f/Vlaamsbelang.gif/330px-Vlaamsbelang.gif"],["Q6199",337,"ideologie","Anarchisme","C","L'anarchisme, ou pensée libertaire, est une idéologie et un mouvement politique qui regroupe plusieurs courants de philosophie politique développés depuis le XIXe siècle sur un ensemble de théories et de pratiques anti-autoritaires fondées sur la démocratie directe et ayant la liberté individuelle, la solidarité et l'égalitarisme comme valeurs fondamentales.",114,"fr:Anarchisme","c:4/4d/Louise.Michel.A.jpg"],["Q182121",338,"ideologie","Anticommunisme","C","Le terme d'anticommunisme englobe, au sens large, l'ensemble des attitudes d'opposition ou d'hostilité envers les aspects théoriques ou pratiques du communisme: l'anticommunisme peut se traduire sous forme de simple prise de position, de discours politique structuré, d'action ou de propagande.",113,"fr:Anticommunisme","c:a/a1/CDU_Wahlkampfplakat_-_kaspl010.JPG"],["Q22649",339,"ideologie","Antisémitisme","C","L'antisémitisme est la discrimination et l'hostilité manifestées à l'encontre des Juifs en tant que groupe ethnique, religieux ou supposément racial.",116,"fr:Antisémitisme","c:5/5a/The_Protocols_of_the_Elders_of_Zion_by_Nilus_%281912%29_-_cleaned.jpg"],["Q6229",340,"ideologie","Autoritarisme","C","L'autoritarisme désigne au sens large le comportement individuel d'une personne dominatrice, ou le comportement d'une organisation entretenue par la domination, la répression ou l'intolérance à la contestation. Dans le champ des sciences politiques, il désigne un mode de fonctionnement politique autocratique, c'est-à-dire un mode d'exercice du pouvoir fondé sur la concentration de l'autorité entre les mains d'un individu, d'une famille ou d'un groupe restreint, au détriment du bien commun, des libertés…",117,"fr:Autoritarisme","https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Democracy_Index_2022.svg/330px-Democracy_Index_2022.svg.png"],["Q6587194",341,"ideologie","Centrisme","PC","Le centrisme ou le centre est une position qui défend un équilibre ou un compromis entre l'idéal de l'égalitarisme et la nécessité d'une hiérarchie sociale, conduisant dans les faits à une modération entre interventionnisme et laissez-faire sur le plan économique, ainsi qu'entre progressisme et conservatisme sur le plan sociétal et culturel.",117,"fr:Centrisme","",{"cats":["politique","politique_fr"]}],["Q6186",342,"ideologie","Communisme","PC","Le communisme est initialement un ensemble de doctrines politiques, issues du socialisme et, pour la plupart, du marxisme, s'opposant au capitalisme et visant à l'instauration d'une société sans classes sociales, sans État, sans salariat et sans valeur d'échange marchande, ainsi que la mise en place d'une totale socialisation économique et démocratique des moyens de production où les biens matériels seraient équitablement répartis selon les besoins.",112,"fr:Communisme","c:9/99/Karl_Marx_Portrait.jpg"],["Q7169",343,"ideologie","Conservatisme","C","Le conservatisme est une philosophie politique qui est en faveur des valeurs traditionnelles et affirme le primat des structures sociales et de la culture sur la raison humaine. Le conservatisme prône la préservation d'une situation ou le retour à une situation passée dans les domaines social, politique, moral, culturel, religieux. En ce sens, il s'oppose au progressisme.",117,"fr:Conservatisme","c:0/00/Conservatism_-_K._LCCN2011647256_%28cropped%29.jpg"],["Q188843",344,"ideologie","Cosmopolitisme","C","Le cosmopolitisme est un concept créé par le philosophe cynique Diogène de Sinope, à partir des mots grecs cosmos, l'univers, et politês, citoyen. Il exprime la possibilité d'être natif d'un lieu et de toucher à l'universalité, sans renier sa particularité. Ce concept a été par la suite repris, approfondi et diffusé dans l'ensemble du monde antique par les philosophes stoïciens, c'est à travers leurs textes qu'il nous est parvenu.",114,"fr:Cosmopolitisme","c:6/65/FougeretCosmopolitan.jpg"],["Q188961",345,"ideologie","Décentralisation","C","La décentralisation consiste en un transfert de pouvoirs de l'État vers des personnes morales de droit public distinctes de lui. Elles disposent:",109,"fr:Décentralisation","c:2/25/Centralization_to_Distributed_Decentralization.jpg"],["Q7174",346,"ideologie","Démocratie","C","La démocratie, du grec ancien δημοκρατία / dēmokratía, combinaison de δῆμος / dêmos, « peuple », dérivé du verbe δαίομαι / daíomai, « distribuer, répartir », et κράτος / krátos, « le pouvoir », dérivé du verbe κρατῶ / kratô, « commander », est, à l'origine, un régime politique dans lequel le pouvoir appartient au peuple, qui l'exerce directement ou par l'intermédiaire de représentants élus.",112,"fr:Démocratie","c:d/d6/P%C3%A8re-Lachaise_-_Division_65_-_Spuller_04.jpg"],["Q171174",347,"ideologie","Démocratie directe","C","La démocratie directe est une forme de démocratie dans laquelle les citoyens exercent directement le pouvoir, sans l'intermédiaire de représentants élus.",114,"fr:Démocratie_directe","c:8/87/Landsgemeinde_Glarus_2006.jpg"],["Q6223",348,"ideologie","Fascisme","R","Le fascisme est un système politique autoritaire qui associe populisme, nationalisme et totalitarisme au nom d'un idéal collectif suprême. Mouvement d'extrême droite révolutionnaire, il s'oppose frontalement à la démocratie parlementaire et au libéralisme traditionnel, mène une lutte contre le socialisme, et remet en cause l'individualisme codifié par la pensée philosophique des Lumières.",119,"fr:Fascisme","c:8/88/Mussolini_and_Hitler_1940_%28retouched%29.jpg"],["Q204886",349,"ideologie","Fédéralisme","C","Le fédéralisme, du latin fœdus, est un type d'organisation où plusieurs entités relativement autonomes sont liées au sein d'un ensemble plus vaste. Il implique donc la diversité dans l'unité.",116,"fr:Fédéralisme","c:d/dc/Carte_des_%C3%89tats_f%C3%A9d%C3%A9raux_dans_le_monde.png"],["Q189746",350,"ideologie","Islamisme","C","L'islamisme est une doctrine prônant l'islam en tant qu'idéologie politique. Elle consiste à mobiliser les musulmans autour d’un projet socio-politique fondé sur les normes et les lois religieuses. Il s'agit du synonyme religieux de l'islam politique. Les adeptes de l'islamisme sont appelés les islamistes.","L'islamisme est une doctrine prônant l'islam en tant qu'idéologie politique.","fr:Islamisme","https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Flag_of_Jihad.svg/330px-Flag_of_Jihad.svg.png"],["Q171990",352,"ideologie","Laissez-faire","C","Le laissez-faire est un concept d'économie politique qui valorise la non-intervention de l'État dans le système économique. Le laissez-faire s'oppose originellement à la doctrine mercantiliste, et aujourd'hui, plus largement, à l'interventionnisme public. La doctrine du laissez-faire vise à enjoindre au pouvoir politique de laisser les agents économiques les plus libres possible.",111,"fr:Laissez-faire","c:0/0a/AdamSmith.jpg"],["Q178598",353,"ideologie","Libertarianisme","C","Le libertarianisme ou libertarisme est une idéologie et philosophie politique développée aux États-Unis autour d'un « groupe de théories qui donnent une priorité stricte à la liberté et au droit naturel, mettant l'accent sur la liberté de choix, l'individualisme et l'association volontaire sur d'autres valeurs telles que l'autorité, la tradition et l'égalité ».",117,"fr:Libertarianisme","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d8/Gadsden_flag.svg/330px-Gadsden_flag.svg.png"],["Q6216",354,"ideologie","Libéralisme","C","Le libéralisme est un courant de pensée qui prône la défense des droits individuels, subjectifs, dans la lignée de John Locke, au nom d'une vision fondée sur l'individu et la coopération volontaire entre les humains.",119,"fr:Libéralisme","c:0/02/La_Libert%C3%A9_guidant_le_peuple_-_Eug%C3%A8ne_Delacroix_-_Mus%C3%A9e_du_Louvre_Peintures_RF_129_-_apr%C3%A8s_restauration_2024.jpg"],["Q155059",355,"ideologie","Léninisme","C","Le léninisme, parfois nommé bolchévisme, est une idéologie politique dérivée du marxisme se réclamant de Vladimir Ilitch Oulianov, dit Lénine, de ses écrits, de son action et de ses idées en matière d'organisation et de stratégie politiques.",113,"fr:Léninisme","c:1/1f/Vladimir_Lenin_in_July_1920_by_Pavel_Zhukov.jpg"],["Q167651",356,"ideologie","Maoïsme","C","Le maoïsme est un courant du communisme révolutionnaire marxiste-léniniste développé au XXe siècle par Mao Zedong, chef du Parti communiste chinois, qui arrive au pouvoir en Chine dès 1949, au terme d'une longue guerre civile contre le Kuomintang et d'une guerre contre l'empire du Japon. Comme Lénine dit avoir adapté les théories de Karl Marx à la Russie, Mao déclare adapter les théories de Marx et de Lénine à la situation politique et économique de la Chine du XXe siècle.",119,"fr:Maoïsme","c:4/4d/Exposition_of_Museu_Oscar_Niemeyer._%C3%81sia%2C_a_Terra%2C_os_Homens%2C_os_Deuses_08.jpg"],["Q7264",357,"ideologie","Marxisme","PC","Le marxisme est un courant de pensée politique, philosophique, sociologique, historique, ethnologique, anthropologique et économique fondé grandement sur les idées de Karl Marx originellement, et d'une certaine mesure également de Friedrich Engels.",118,"fr:Marxisme","c:7/79/Marx_and_Engels.jpg"],["Q211930",358,"ideologie","Marxisme-léninisme","C","Le marxisme-léninisme est un courant politique communiste qui se réclame d’une continuité entre la pensée de Karl Marx et Friedrich Engels et les apports théoriques et stratégiques de Lénine. Apparue après la mort de ce dernier, l’expression s’impose progressivement comme doctrine officielle de l’Union soviétique et comme ligne dominante d’une grande partie du mouvement communiste international, notamment parmi les partis liés d'abord à l’Internationale communiste.",118,"fr:Marxisme-léninisme","c:5/55/Bundesarchiv_Bild_183-19400-0029%2C_Berlin%2C_Marx-Engels-Platz%2C_Demonstration.jpg"],["Q7310",359,"ideologie","Nazisme","PC","Le national-socialisme, couramment abrégé nazisme, est l'idéologie politique du Parti national-socialiste des travailleurs allemands, parti politique d'extrême droite, fondé en Allemagne en 1920 et dirigé par Adolf Hitler.",109,"fr:Nazisme","https://upload.wikimedia.org/wikipedia/commons/thumb/9/9c/Nazi_Swastika.svg/330px-Nazi_Swastika.svg.png"],["Q162719",360,"ideologie","Néolibéralisme","C","Le terme de néolibéralisme désigne aujourd'hui un ensemble d'analyses ou de doctrines économiques et sociales inspirées du libéralisme économique, aux définitions multiples et parfois concurrentes. Globalement, le terme est flou, et des courants économiques et politiques différents voire opposés peuvent être qualifiés de néolibéraux. Il est souvent un qualificatif critique et rarement revendiqué par ceux qu'il désigne qui préfèrent souvent se désigner simplement comme libéral.",119,"fr:Néolibéralisme","c:d/d5/The_World_Bank_Group_building.JPG"],["Q58848",361,"ideologie","Pacifisme","C","Le pacifisme possède deux acceptions possibles incluant l'action des partisans de la paix, ou une doctrine de la non-violence. Bien que reliés, les deux concepts se distinguent du point de vue de la théorie et de la pratique. Le pacifisme est la doctrine et l'action des partisans de la paix ou du rétablissement de la paix.",112,"fr:Pacifisme","https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Peace_symbol_%28bold%29.svg/330px-Peace_symbol_%28bold%29.svg.png"],["Q180490",362,"ideologie","Populisme","C","Le populisme désigne toute approche politique ou stratégie électorale qui se fonde sur une opposition dichotomique entre le peuple et les élites politiques, économiques, médiatiques, culturelles et/ou intellectuelles, en se réclamant du premier.",114,"fr:Populisme_(politique)","c:8/82/Bryan%2C_Judge_magazine%2C_1896.jpg"],["Q8461",363,"ideologie","Racisme","C","Le racisme est à la fois un rapport social et une idéologie. En tant que rapport social, il est souvent analysé dans le cadre de la colonisation et de l'impérialisme comme un système de domination sur les personnes racisées. Selon les sciences sociales, le racisme s’inscrit dans une dynamique de domination sociale à prétexte racial.","Le racisme est à la fois un rapport social et une idéologie.","fr:Racisme","c:4/4a/%22Colored%22_drinking_fountain_from_mid-20th_century_with_african-american_drinking.jpg"],["Q877848",364,"ideologie","Républicanisme","C","Le républicanisme est une idéologie politique centrée sur la citoyenneté dans un État organisé en république. Dans son acception politique, le républicanisme défend l'idée selon laquelle l'objectif d'un État et le sens de son existence, comme de ses décisions, doivent être le bien commun et non la prospérité de ses seuls dirigeants.","Le républicanisme est une idéologie politique centrée sur la citoyenneté dans un État organisé en république.","fr:Républicanisme","c:5/55/La_Republica_Espa%C3%B1ola_En_El_Mundo_revista_La_Flaca%2C_28_de_marzo_de_1873.JPG"],["Q42388",365,"ideologie","Sionisme","E","Le sionisme est historiquement le mouvement national du peuple juif visant à son autodétermination politique par la formation d'un foyer national juif en Terre d'Israël.",115,"fr:Sionisme","c:d/dc/Theodor_Herzl_retouched.jpg"],["Q121254",366,"ideologie","Social-démocratie","C","La social-démocratie désigne un courant politique et économique, apparu au XIXe siècle, qui tend à incorporer certains éléments du socialisme dans une démocratie libérale. L'expression recouvre à la fois la dénomination employée par divers partis socialistes, la forme d'organisation de ceux-ci, un courant idéologique et une pratique politique.",118,"fr:Social-démocratie","https://upload.wikimedia.org/wikipedia/commons/thumb/e/e9/Pu%C3%B1o_y_rosa.svg/330px-Pu%C3%B1o_y_rosa.svg.png"],["Q7272",367,"ideologie","Socialisme","PC","Le socialisme est une philosophie économique et politique qui englobe un large éventail de courants de pensées et de mouvements, dont le point commun est de rechercher une organisation sociale et économique plus juste. Le but originel du socialisme est d'obtenir l'égalité sociale, ou du moins une réduction des inégalités et, notamment pour les courants d'inspirations marxiste et anarchiste, d'établir une société sans classes sociales.",116,"fr:Socialisme","c:7/7a/Madrid_may_day375.jpg"],["Q189280",368,"ideologie","Socialisme démocratique","C","L'expression socialisme démocratique désigne, dans son acception la plus répandue, un ensemble de courants socialistes caractérisés par la volonté de construire une société socialiste, où existerait l'égalité la plus grande possible et où régnerait la justice sociale, tout en respectant des principes démocratiques.",118,"fr:Socialisme_démocratique",""],["Q179121",369,"ideologie","Stalinisme","C","Le mot stalinisme désigne l’idéologie et la pratique politique des partis communistes ayant adopté la ligne politique définie par les partisans de Joseph Staline, secrétaire général du Parti communiste de l'Union soviétique. Par extension, ces partis et leurs membres ont été qualifiés de staliniens, terme qu’aurait forgé Lazare Kaganovitch au cours d’un repas en présence de Staline.",117,"fr:Stalinisme","c:b/bb/Isaak_Brodsky_stalin02.jpg"],["Q190044",370,"ideologie","Technocratie","C","La technocratie est une forme de gouvernement où la place des experts techniques et de leurs méthodes est centrale dans les prises de décision. Selon le Dictionnaire de la langue philosophique, la technocratie est « la condition politique dans laquelle le pouvoir effectif appartient à des techniciens appelés « technocrates » ».",119,"fr:Technocratie",""],["Q128135",371,"ideologie","Totalitarisme","C","Le totalitarisme est un régime politique n'admettant aucune opposition organisée, politique ou syndicale, individuelle ou collective, et exerçant une mainmise sur l'État et la totalité des activités des sphères publique et privée de la société. Un tel système restreint les relations des individus au seul État.",118,"fr:Totalitarisme","c:f/f0/Benito_Mussolini_and_Adolf_Hitler.jpg"],["Q181133",372,"ideologie","Trotskisme","C","Le trotskisme, parfois nommé bolchévisme-léninisme, est une philosophie politique de type marxiste se réclamant de Léon Trotski, de ses écrits, de son action et de ses idées. L'expression est d'abord apparue chez les staliniens, pour laisser entendre que les idées défendues par Trotski, dans les années 1920 seraient opposées à celles de Lénine.",119,"fr:Trotskisme","c:9/98/TrotskiEnElFrente1918.png"],["Q2855609",373,"ideologie","Écologisme","C","L'écologisme, ou environnementalisme, est un ensemble de courants de pensée et un corpus de valeurs et de propositions, dont l'orientation de l'activité politique ou parapolitique vise au respect, à la protection, à la préservation ou à la restauration de l'environnement.",119,"fr:Écologisme","c:4/4e/Beech_Forest_%28AU%29%2C_Great_Otway_National_Park%2C_Beauchamp_Falls_--_2019_--_1271.jpg"],["Q188958",374,"ideologie","Égalitarisme","C","L'égalitarisme est une doctrine politique prônant l'égalité des citoyens en matière politique, économique, voire même sociale selon les contextes. Dans un sens plus général, l'égalitarisme désigne une école de pensée qui donne la priorité à l'égalité de tous.",117,"fr:Égalitarisme","https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Scale_of_Justice.svg/330px-Scale_of_Justice.svg.png"],["Q83372",376,"mouvement","Bolcheviks","C","Les bolcheviks, bolchéviks, bolcheviques, ou bolchéviques sont les membres d'une des deux factions du Parti ouvrier social-démocrate de Russie, l'autre étant composée des mencheviks. La faction bolchevique est créée en 1903 sous la direction de Lénine. Elle est majoritaire au sein du POSDR en 1903, d'où son nom en russe, et devient un parti indépendant en 1912.",115,"fr:Bolcheviks","c:0/00/Presidium_of_the_9th_Congress_of_the_Russian_Communist_Party_%28Bolsheviks%29.jpg"],["Q7252",377,"mouvement","Féminisme","C","Le féminisme est un ensemble de mouvements et d'idées politiques, sociales et culturelles. La définition globale de ce terme lui donne pour objectif de promouvoir l'égalité entre les femmes et les hommes en militant pour les droits des femmes, et ce, sur le principe fondamental que les hommes et les femmes sont égaux et doivent être considérés comme tels dans la société.","Le féminisme est un ensemble de mouvements et d'idées politiques, sociales et culturelles.","fr:Féminisme","c:3/3b/8marchrallydhaka_%2855%29.JPG"],["Q2914207",378,"mouvement","Féminisme radical","C","Le féminisme radical est un courant du féminisme qui considère que l'oppression spécifique des femmes au bénéfice des hommes résulte, avant toute autre cause, du patriarcat. Les féministes radicales se donnent pour objectif d'abolir cet ordre social; elles dénoncent notamment l'essentialisation du rôle social des femmes.",117,"fr:Féminisme_radical","c:0/08/Feminist_Stencil_Graffito_S%C3%A3o_Paulo_March_2012-14.jpg"],["Q3042087",379,"mouvement","Houthis","L","Les houthis ou houthistes sont une organisation islamiste chiite zaydite yéménite, disposant d'une branche politique et d'une branche armée. Elle est classée terroriste par de nombreux États.",119,"fr:Houthis","https://upload.wikimedia.org/wikipedia/commons/thumb/3/38/Slogan_of_the_Houthi_Movement.svg/330px-Slogan_of_the_Houthi_Movement.svg.png"],["Q212983",380,"mouvement","Jacobitisme","C","Le « jacobitisme » historique est un mouvement politique proche des tories entre 1688 et 1807, composé de ceux qui soutenaient la dynastie détrônée des Stuart et considéraient comme usurpateurs tous les rois et les reines britanniques ayant régné pendant cette période. Soutenu par les monarchies catholiques française et espagnole, il était surtout implanté en Irlande et dans les Highlands d'Écosse qui furent le théâtre de plusieurs révoltes soutenues par la France.",114,"fr:Jacobitisme","https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Flag_of_Prince_Charles_Edward_Stuart.svg/330px-Flag_of_Prince_Charles_Edward_Stuart.svg.png"],["Q83896",381,"mouvement","Jeunes-Turcs","C","Les Jeunes-Turcs sont un mouvement politique nationaliste, moderniste et réformateur ottoman, officiellement connu sous le nom de Comité union et progrès, dont les chefs ont mené une rébellion contre le sultan Abdülhamid II, planifié le génocide arménien et mis en œuvre la turquisation de l'Anatolie.",119,"fr:Jeunes-Turcs","c:0/02/Jon-turkler-1.jpg"],["Q1159675",382,"mouvement","Luddisme","C","Le luddisme est, selon l'expression de l'historien britannique Edward P. Thompson, un « violent conflit social » qui, dans l'Angleterre des années 1811-1812, a opposé des artisans — tondeurs et tricoteurs sur métiers à bras du West Riding, du Lancashire du sud et d'une partie du Leicestershire et du Derbyshire — aux employeurs et aux manufacturiers qui favorisaient l'emploi de machines dans le travail de la laine et du coton.","Le luddisme est, selon l'expression de l'historien britannique Edward P.","fr:Luddisme","c:7/73/Luddite.jpg"],["Q208701",383,"mouvement","Mouvement ouvrier","C","Le terme de mouvement ouvrier désigne l'ensemble des mouvements et partis organisés, à partir de l'époque de la révolution industrielle, dans l'objectif d'améliorer les conditions d'existence de la classe ouvrière. Cette définition inclut principalement le syndicalisme, mais aussi les partis politiques et autres organisations en étant issus ou s'en étant réclamés et plus largement les différentes formes d'action politique et sociale ayant lutté pour, représenté, ou estimé représenter, les intérêts de la classe…",111,"fr:Mouvement_ouvrier","https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Red_flag_waving.svg/330px-Red_flag_waving.svg.png"],["Q6235",384,"mouvement","Nationalisme","C","Le nationalisme est un principe politique apparu à la fin du XVIIIe siècle, qui tend à légitimer l'existence d'un État-nation pour chaque peuple, défini par des caractéristiques propres et communes à ses membres, comme une langue, des traditions historiques et culturelles ou des valeurs politiques.",113,"fr:Nationalisme","c:f/fb/Flag_Map_of_World_%282025%29.png"],["Q282739",385,"mouvement","Panafricanisme","C","Le panafricanisme est un mouvement et une idéologie politique qui promeut l'indépendance totale du continent africain, et encourage la pratique de la solidarité entre les Africains et les personnes d'ascendance africaine, où qu'ils soient dans le monde, indépendamment de leurs origines ethniques, leurs appartenances religieuses, ou leurs apparences physiques.",118,"fr:Panafricanisme","c:2/21/Africa_satellite_orthographic.jpg"],["Q155812",386,"mouvement","Pangermanisme","C","Le pangermanisme est un mouvement politique irrédentiste du XIXe siècle visant l'unité de tous les germanophones d'Europe, ou identifiés comme tels par les penseurs de cette théorie, dont découle la volonté de mettre en place la Grande Allemagne, expression traduite de Großdeutschland en allemand, provenant du latin Magna Germania qui désigne la Germanie antique.",112,"fr:Pangermanisme","c:a/ad/Karte_der_deutschen_Mundarten_%28Brockhaus%29.jpg"],["Q192957",388,"mouvement","Réaction politique","C","Une réaction désigne la politique prônant et mettant en œuvre un retour à une situation passée réelle ou fantasmée, en révoquant une série de changements sociaux, moraux, économiques et politiques. Un partisan de la réaction est nommé « réactionnaire ». Le terme s'oppose à « progressiste ».",118,"fr:Réaction_(politique)","c:7/71/Le_suffrage_%C3%A0_2_tours_vaincra_la_r%C3%A9action.jpg"],["Q42418",390,"mouvement","Talibans","C","Les talibans ou taliban sont des fondamentalistes islamistes regroupés dans une organisation militaire, politique et religieuse dénommée l'émirat islamique d'Afghanistan puis Mouvement islamique des talibans, au pouvoir entre 1996 et 2001 et depuis 2021. Ce mouvement est dirigé par Haibatullah Akhundzada, qui a été proclamé commandeur des croyants de l'émirat le 25 mai 2016.",116,"fr:Talibans","https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Flag_of_the_Taliban.svg/330px-Flag_of_the_Taliban.svg.png"],["Q189225",391,"mouvement","Zélotes","C","Les Zélotes sont les membres d'un mouvement politico-religieux juif du Ier siècle. Les Zélotes incitent le peuple de la province de Judée à se rebeller contre l'Empire romain et l'expulser par la force des armes. Ils ont joué un rôle de tout premier plan pendant la Grande révolte juive qui a abouti à la destruction du Temple de Jérusalem en l'an 70.","Les Zélotes sont les membres d'un mouvement politico-religieux juif du Ier siècle.","fr:Zélotes","c:9/9f/Baptisterio_Neoniano_-_Judas_Zelote.jpg"],["Q131372",392,"mouvement","Église hussite","C","Le hussitisme est un mouvement religieux et social inspiré par les doctrines de Jan Hus. Il continue d'inspirer des mouvements religieux actuels: les Frères moraves et l'Église hussite tchécoslovaque.","Le hussitisme est un mouvement religieux et social inspiré par les doctrines de Jan Hus.","fr:Église_hussite","c:8/89/Ussita_pavese_shield_Prag_Museum_1429.jpg"],["Q8880",394,"institution","Commission européenne","C","La Commission européenne est l'une des principales institutions de l'Union européenne, avec le Conseil de l'Union européenne, le Parlement européen et le Conseil européen.",113,"fr:Commission_européenne","c:b/bc/Reuni%C3%B3n_con_Vicepresidenta_de_la_Comisi%C3%B3n_Europea_y_Alta_Representante_para_la_Pol%C3%ADtica_Exterior_y_de_Seguridad_de_la_UE_%286856953422%29.jpg"],["Q11268",395,"institution","Congrès des États-Unis","PC","Le Congrès des États-Unis est la législature bicamérale du gouvernement fédéral des États-Unis, constituant sa branche législative. Ses deux chambres: la chambre haute qui est le Sénat composée de 100 sénateurs, et la chambre basse qui est la Chambre des représentants, composée de 435 représentants.",118,"fr:Congrès_des_États-Unis","https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Seal_of_the_United_States_Congress.svg/330px-Seal_of_the_United_States_Congress.svg.png",{"cats":["politique","usa"]}],["Q8908",396,"institution","Conseil de l'Europe","C","Le Conseil de l'Europe est une organisation internationale qui rassemble environ 675 millions de ressortissants de 46 États membres, par le biais des normes juridiques dans les domaines de la protection des droits de l'homme, du renforcement de la démocratie et de la prééminence du droit en Europe. Le Conseil de l'Europe est doté de la personnalité juridique, reconnue en droit international public. Cette organisation intergouvernementale est instituée le 5 mai 1949 par le traité de Londres.",117,"fr:Conseil_de_l'Europe","https://upload.wikimedia.org/wikipedia/fr/thumb/4/49/Logo_du_Conseil_de_l%27Europe_%28version_r%C3%A9vis%C3%A9e_2013%29.svg/330px-Logo_du_Conseil_de_l%27Europe_%28version_r%C3%A9vis%C3%A9e_2013%29.svg.png"],["Q8896",397,"institution","Conseil de l'Union européenne","C","Le Conseil de l'Union européenne, officiellement appelé le Conseil et parfois, de façon informelle, Conseil des ministres de l'Union européenne, est l'une des principales institutions de l'Union européenne, avec la Commission européenne, le Conseil européen et le Parlement européen. C'est un organe institutionnel exécutif mais aussi législatif de l'Union européenne, qui décide des actes législatifs et budgétaires.",111,"fr:Conseil_de_l'Union_européenne","c:c/c8/European_Council_%2838185339475%29.jpg"],["Q37470",398,"institution","Conseil de sécurité des Nations unies","C","Le Conseil de sécurité des Nations unies est l'organe exécutif de l'Organisation des Nations unies. Il est défini comme ayant « la responsabilité principale du maintien de la paix et de la sécurité internationale » selon la Charte des Nations unies et dispose pour cela de pouvoirs spécifiques tels que l'établissement de sanctions internationales et l'intervention militaire.","Le Conseil de sécurité des Nations unies est l'organe exécutif de l'Organisation des Nations unies.","fr:Conseil_de_sécurité_des_Nations_unies","https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Emblem_of_the_United_Nations.svg/330px-Emblem_of_the_United_Nations.svg.png"],["Q47488",399,"institution","Cour pénale internationale","PC","La Cour pénale internationale est une juridiction pénale internationale créée en 1998, permanente et à vocation universelle, complémentaire de la Cour internationale de justice créée en 1945. Elle est chargée de juger « a) le crime de génocide, b) les crimes contre l'humanité, c) les crimes de guerre, d) le crime d'agression ». La Cour inscrit son action dans une dimension préventive et dissuasive: son objectif est de responsabiliser les individus, qu'il s'agisse d'autorités civiles ou militaires.",111,"fr:Cour_pénale_internationale","https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/International_Criminal_Court_logo.svg/330px-International_Criminal_Court_logo.svg.png"],["Q1764511",400,"institution","Groupe des sept","C","Le Groupe des sept est un groupe de discussion et de partenariat économique de sept pays réputés en 1975 pour être les plus grandes puissances avancées du monde qui détiennent environ les deux tiers de la richesse nette mondiale: Allemagne, Canada, États-Unis, France, Italie, Japon et Royaume-Uni. Le groupe rassemble 7 des 11 pays avec le plus important PIB du monde, avec l'absence notable de la Chine qui occupe le 2e rang et de l'Inde qui occupe le 6e rang.",118,"fr:Groupe_des_sept_(économie)","https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Group_of_Seven_%28G7%29_Countries.svg/330px-Group_of_Seven_%28G7%29_Countries.svg.png"],["Q19771",401,"institution","Groupe des vingt","C","Le Groupe des vingt est un forum intergouvernemental composé de dix-neuf des pays aux économies les plus développées du monde, dont les chefs d'État, chefs de gouvernement, ministres des finances et chefs des banques centrales se réunissent annuellement. Il est créé en 1999, après une succession de crises financières dans les années 1990. Il vise à favoriser la concertation internationale, en intégrant le principe d'un dialogue élargi tenant compte du poids économique croissant pris par un certain nombre de pays.",119,"fr:Groupe_des_vingt","https://upload.wikimedia.org/wikipedia/fr/thumb/5/53/LogoG20new.gif/330px-LogoG20new.gif"],["Q1065",404,"institution","Organisation des Nations unies","R","L'Organisation des Nations unies est une organisation internationale regroupant 193 États membres depuis le 14 juillet 2011. Elle a été instituée le 24 octobre 1945 par la ratification de la Charte des Nations unies signée le 26 juin 1945 par les représentants de 51 États. Elle remplace alors la Société des Nations.",118,"fr:Organisation_des_Nations_unies","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Flag_of_the_United_Nations.svg/330px-Flag_of_the_United_Nations.svg.png"],["Q7184",405,"institution","Organisation du traité de l'Atlantique nord","PC","L'Organisation du traité de l'Atlantique nord est l'organisation politico-militaire mise en place par les pays signataires du traité de l'Atlantique nord afin de pouvoir remplir leurs obligations de défense et de sécurité collectives. Elle est le plus souvent désignée par son acronyme OTAN, qui est prononcé, mais elle est aussi fréquemment nommée l'Alliance atlantique ou l'Alliance nord-atlantique, plus rarement l'Alliance euro-atlantique ou l'Alliance transatlantique, ou parfois, encore plus brièvement,…",110,"fr:Organisation_du_traité_de_l'Atlantique_nord","https://upload.wikimedia.org/wikipedia/commons/thumb/3/37/Flag_of_NATO.svg/330px-Flag_of_NATO.svg.png"],["Q41644",406,"institution","Pacte de Varsovie","C","Le Traité d'amitié, de coopération et d'assistance mutuelle, dit « pacte de Varsovie », est une ancienne alliance militaire groupant les pays d'Europe de l'Est avec l'URSS dans un vaste ensemble économique, politique et militaire. Il est conclu le 14 mai 1955 entre la plupart des pays communistes du bloc soviétique par un traité d’amitié, de coopération et d’assistance mutuelle.",113,"fr:Pacte_de_Varsovie","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1b/Warsaw_Pact_Logo.svg/330px-Warsaw_Pact_Logo.svg.png"],["Q11010",408,"institution","Parlement du Royaume-Uni","C","Le Parlement du Royaume-Uni de Grande-Bretagne et d'Irlande du Nord est l'institution législative suprême du Royaume-Uni, des territoires britanniques d'outre-mer et des dépendances de la Couronne. Lui seul dispose de la suprématie parlementaire, c'est-à-dire du pouvoir de légiférer sur tous les autres organes politiques du Royaume-Uni et de ses territoires.",108,"fr:Parlement_du_Royaume-Uni","https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Crowned_Portcullis_redesign_2018.svg/330px-Crowned_Portcullis_redesign_2018.svg.png"],["Q8889",409,"institution","Parlement européen","R","Le Parlement européen est l'organe parlementaire de l'Union européenne élu au suffrage universel direct. Il partage avec le Conseil de l'Union européenne le pouvoir législatif de l'Union européenne. Le Parlement européen est actuellement composé de 720 députés, qui représentent environ 360 millions d'électeurs inscrits — participant aux élections européennes — provenant des 27 États membres et répartis selon des règles fixées dans les traités.","Le Parlement européen est l'organe parlementaire de l'Union européenne élu au suffrage universel direct.","fr:Parlement_européen","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/European_Parliament_logo.svg/330px-European_Parliament_logo.svg.png",{"cats":["politique","politique_fr"]}],["Q1137059",410,"institution","Parlement fédéral belge","C","Le Parlement fédéral est l'organe législatif de l'État fédéral en Belgique. Il est constitué de deux chambres: la Chambre des représentants, qui en est la chambre basse, et le Sénat, qui en est la chambre haute.","Le Parlement fédéral est l'organe législatif de l'État fédéral en Belgique.","fr:Parlement_fédéral_(Belgique)","https://upload.wikimedia.org/wikipedia/commons/thumb/1/19/State_Coat_of_Arms_of_Belgium.svg/330px-State_Coat_of_Arms_of_Belgium.svg.png"],["Q38130",411,"institution","Société des Nations","C","La Société des Nations était une organisation internationale établie par le traité de Versailles en 1919, et dissoute en 1946. Le traité est élaboré au cours de la conférence de la paix de Paris, pendant laquelle est signé le « Pacte », terme désignant un traité multilatéral plus solennel, qui établit la SDN, afin de préserver la paix en Europe après la fin de la Première Guerre mondiale.",117,"fr:Société_des_Nations","https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Emblem_of_the_League_of_Nations_%281939%29.svg/330px-Emblem_of_the_League_of_Nations_%281939%29.svg.png"],["Q458",412,"institution","Union européenne","R","L'Union européenne est une union politico-économique sui generis d'États européens, qui lui délèguent ou transmettent sans limite de temps, par traité, l'exercice de certaines de leurs compétences souveraines, afin qu'elles soient régies par des organes communautaires.",117,"fr:Union_européenne","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Flag_of_Europe.svg/330px-Flag_of_Europe.svg.png"],["Q184558",413,"notion","Absolutisme","C","L'absolutisme est un concept lié aux réactions de régimes politiques centraux, généralement monarchiques, visant à l'affranchissement des contrepoids liés aux premières formes de séparation des pouvoirs qui ont suivi les formes consultatives.",114,"fr:Monarchie_absolue","c:2/2d/%D8%A7%D9%84%D8%B5%D9%88%D8%B1%D8%A9_%D8%A7%D9%84%D8%B1%D8%B3%D9%85%D9%8A%D8%A9_%D9%84%D8%AE%D8%A7%D8%AF%D9%85_%D8%A7%D9%84%D8%AD%D8%B1%D9%85%D9%8A%D9%86_%D8%A7%D9%84%D8%B4%D8%B1%D9%8A%D9%81%D9%8A%D9%86_%D8%A7%D9%84%D9%85%D9%84%D9%83_%D8%B3%D9%84%D9%85%D8%A7%D9%86_%D8%A8%D9%86_%D8%B9%D8%A8%D8%AF%D8%A7%D9%84%D8%B9%D8%B2%D9%8A%D8%B2_%D8%A2%D9%84_%D8%B3%D8%B9%D9%88%D8%AF.jpg"],["Q7755",415,"notion","Constitution","C","Une constitution est une loi fondamentale qui fixe l'organisation et le fonctionnement d'un organisme, généralement d'un État ou d'un ensemble d'États.",115,"fr:Constitution","c:6/6f/Constitution_de_l%27an_XII._Page_1_-_Archives_Nationales_-_AE-II-1512.jpg"],["Q86659138",416,"notion","Cordon sanitaire","C","Le « cordon sanitaire » est une pratique politique visant à exclure les partis politiques d'extrême droite de toute majorité politique. L'expression est employée par les commentateurs pour décrire des situations où des partis rivaux se réunissent contre des partis jugés menaçants pour la démocratie.",115,"fr:Cordon_sanitaire_(politique)",""],["Q45382",417,"notion","Coup d'État","C","Un coup d'État est un renversement du pouvoir par une personne investie d'une autorité, de façon illégale et souvent brutale. On le distingue d'une révolution en ce que celle-ci est populaire. Le putsch est un coup d'État réalisé par la force des armes. Une révolution de palais est une forme de coup d'État dans laquelle le régime politique reste essentiellement le même, mais les principaux titulaires du pouvoir sont illégalement arrêtés voire assassinés, et remplacés par de nouveaux.",116,"fr:Coup_d'État","c:4/44/Bouchot_-_Le_general_Bonaparte_au_Conseil_des_Cinq-Cents.jpg"],["Q192914",418,"notion","Culte de la personnalité","C","L’expression « culte de la personnalité » a été popularisée en février 1956 pour dénoncer la dérive autoritaire et la propagande autour de Joseph Staline, par son successeur Nikita Khrouchtchev lors du XXe Congrès du Parti communiste de l'Union soviétique.",117,"fr:Culte_de_la_personnalité","c:a/a6/Monumento_en_strato_Nguyen_Hue_%28Ho-%C4%88i-Min-urbo%29_06.jpg"],["Q480498",419,"notion","Destitution","C","La destitution est une procédure de droit qui vise à priver quelqu'un de sa charge ou de sa fonction. Elle est notamment utilisée par l'organe détenant le pouvoir législatif à la suite d'une mise en accusation, ou en anglais impeachment /ɪmˈpiːt͡ʃmənt/, d'un officiel du gouvernement. Dans les pays où cette procédure existe, elle nécessite généralement une large majorité des voix.","La destitution est une procédure de droit qui vise à priver quelqu'un de sa charge ou de sa fonction.","fr:Destitution","c:b/b8/House_of_Representatives_Votes_to_Adopt_the_Articles_of_Impeachment_Against_Donald_Trump.jpg"],["Q317",420,"notion","Dictature","C","Une dictature est un régime politique dans lequel une personne ou un groupe de personnes exercent tous les pouvoirs de façon absolue, sans qu'aucune loi ou institution ne les limitent. Une dictature est un régime autoritaire, bien qu'à l'inverse un régime autoritaire ne soit pas nécessairement une dictature. Elle peut avoir des lois, des institutions, voire un parlement avec des députés élus, mais pas librement et ne représentant donc pas des contre-pouvoirs.",118,"fr:Dictature","c:6/60/Hitler_N%C3%BCrnberg_1935.jpg"],["Q8458",422,"notion","Droits de l'homme","C","Les droits de l'homme, également appelés droits humains ou droits de la personne, sont un concept à la fois philosophique, juridique et politique, selon lequel tout être humain possède des droits universels, inaliénables, quel que soit le droit positif ou d'autres facteurs locaux tels que l'ethnie, la nationalité ou la religion.",107,"fr:Droits_de_l'homme","c:2/24/Eleanor_Roosevelt_UDHR.jpg"],["Q7813",423,"notion","Déclaration universelle des droits de l'homme","C","La Déclaration universelle des droits de l'homme est adoptée par l'Assemblée générale des Nations unies le 10 décembre 1948 à Paris, au palais de Chaillot, par la résolution 217 A. Elle précise les droits fondamentaux de l'homme.",118,"fr:Déclaration_universelle_des_droits_de_l'homme","c:2/24/Eleanor_Roosevelt_UDHR.jpg"],["Q2921172",424,"notion","Gauche et droite","C","En politique, la « gauche » et la « droite » est une manière de catégoriser les idéologies, les idées, les politiciens ou les partis selon leurs positions politiques et leurs valeurs. L'opposition entre la droite et la gauche structure fortement l'échiquier politique, même si certains partis se définissent comme centristes, ou revendiquent un dépassement du clivage.",118,"fr:Gauche_et_droite_(politique)","https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Sch%C3%A9ma_politique_gauche_droite.svg/330px-Sch%C3%A9ma_politique_gauche_droite.svg.png"],["Q187117",426,"notion","Lobbying","C","En politique, le lobbying, lobbyisme ou représentation d'intérêts, est l'acte de tenter légalement d'influencer les actions, les politiques ou les décisions des représentants du gouvernement, des législateurs ou des organismes de réglementation.",115,"fr:Lobbying","c:0/09/The_Lobby_of_The_House_of_Commons%2C_Vanity_Fair%2C_1886-11-30.jpg"],["Q7269",427,"notion","Monarchie","C","La monarchie est un régime politique où l'unité du pouvoir est symbolisée par une seule personne, appelée « monarque » et n'est pas nécessairement une royauté. Elle peut être héréditaire ou élective. Selon la définition de Montesquieu, une monarchie se définit par le gouvernement absolu d'un seul, mais ce pouvoir est limité par des lois.",118,"fr:Monarchie","https://upload.wikimedia.org/wikipedia/commons/thumb/6/64/World_Monarchies.svg/330px-World_Monarchies.svg.png"],["Q41614",428,"notion","Monarchie constitutionnelle","C","Une monarchie constitutionnelle est un type de régime politique qui reconnaît un monarque élu ou héréditaire comme chef de l'État, mais où une constitution limite ses pouvoirs.",119,"fr:Monarchie_constitutionnelle","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Government_constitutional_monarchy_2022.svg/330px-Government_constitutional_monarchy_2022.svg.png"],["Q7281",429,"notion","Propagande","C","La propagande est un ensemble de techniques de persuasion mises en œuvre pour propager, par tous les moyens disponibles, une opinion ou une idéologie. Ces techniques sont exercées sur une population afin de l'influencer, voire de l'endoctriner. Elle se caractérise par une manipulation mentale qui mélange sciemment l’information et l’opinion, afin d'éliminer le pluralisme des points de vue et d'empêcher l'exercice de l'esprit critique.",107,"fr:Propagande","c:2/24/Keep_this_Horror_From_Your_Home._Invest_10_Percent_in_War_Bonds_Back_Up_our_Battleskies%5E_-_NARA_-_534105.jpg"],["Q124425",430,"notion","Rideau de fer","C","Le rideau de fer est la frontière physique et idéologique au sein de l'Europe, entre les pays du bloc de l'Ouest et ceux du bloc de l'Est pendant la guerre froide.",115,"fr:Rideau_de_fer","c:4/43/%C5%BDelezn%C3%A1_opona%2C_%C4%8C%C3%AD%C5%BEov.jpg"],["Q3136557",431,"notion","Réformes de l'État belge","C","Les réformes de l'état belge sont une série de six réformes lancées en Belgique à la fin des années 1960, avec, pour toile de fond, la naissance du fédéralisme belge afin de tenter d’apporter une solution aux tensions communautaires dans le Royaume, entrainant la fin de l'état-nation unitaire et la transition vers un état fédéral.",116,"fr:Réformes_de_l'État_belge","https://upload.wikimedia.org/wikipedia/commons/thumb/1/1e/BelgieGemeenschappenkaart.svg/330px-BelgieGemeenschappenkaart.svg.png"],["Q43109",432,"notion","Référendum","C","Un référendum est une procédure par laquelle les citoyens d'une collectivité sont appelés à se prononcer directement sur une question d'ordre politique ou institutionnel. Il s'agit d'un mode de consultation par lequel une autorité publique soumet à l'approbation ou au rejet du corps électoral une proposition concernant « une mesure qu'une autre autorité a prise ou envisage de prendre ».",116,"fr:Référendum","c:e/e9/Bulletin_de_vote_r%C3%A9f%C3%A9rendum_URSS_1991.jpg"],["Q7270",433,"notion","République","C","La république est un mode d'organisation d'un pays dans lequel le pouvoir est exercé par des représentants de la population, généralement élus, et où le chef d'État n'est pas héréditaire et n'est pas le seul à détenir le pouvoir. Une république est le contraire d'une monarchie héréditaire, mais n'est pas toujours synonyme de démocratie.",112,"fr:République","c:7/7c/Honor%C3%A9_daumier%2C_la_repubblica_sfama_i_suoi_figli_e_gli_istruisce%2C_1848.JPG"],["Q319891",434,"notion","Suffrage universel","C","Le suffrage universel consiste en la reconnaissance du droit de vote à l'ensemble des citoyens en âge de voter. Il est défini par opposition au suffrage restreint qui réserve le droit de vote à certains citoyens, en particulier au suffrage censitaire ou au suffrage capacitaire. Il est l'expression de la volonté générale dans un régime démocratique.","Le suffrage universel consiste en la reconnaissance du droit de vote à l'ensemble des citoyens en âge de voter.","fr:Suffrage_universel","https://upload.wikimedia.org/wikipedia/commons/thumb/2/2b/Universal_suffrage_lexical%2C_World%2C_2024_%28cropped%29.svg/330px-Universal_suffrage_lexical%2C_World%2C_2024_%28cropped%29.svg.png",{"cats":["politique","politique_fr"]}],["Q79896",435,"notion","Séparation des pouvoirs","C","La séparation des pouvoirs législatif, exécutif et judiciaire est un principe fondamental des démocraties représentatives. Au contraire, les régimes despotiques et dictatoriaux pratiquent une concentration des pouvoirs. Ces pouvoirs sont influencés par des contre-pouvoirs. L'indépendance et la séparation de ces pouvoirs est un idéal délicat quand bien même la bonne volonté est à l'œuvre.",105,"fr:Séparation_des_pouvoirs","c:7/7b/Separation_of_powers_%28FR%29.png"],["Q40231",436,"notion","Élection","C","L'élection est la désignation, par le vote d'électeurs, de représentants destinés à les représenter ou occuper une fonction en leur nom.",114,"fr:Élection","c:f/fc/Election_MG_3455.JPG"]]]);